screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const validationResultIdx = tables.findIndex(t => t.tableName === '受注データ検証結果');
  const trustScoreIdx = tables.findIndex(t => t.tableName === '信頼度スコア');
  const duplicateIdx = tables.findIndex(t => t.tableName === '重複受注検出結果');
  const conflictIdx = tables.findIndex(t => t.tableName === 'チャネル間矛盾検出結果');
  const missingIdx = tables.findIndex(t => t.tableName === '入力漏れ検出結果');
  const priorityIdx = tables.findIndex(t => t.tableName === '修正対象優先度リスト');

  // ============ 1. KPI 計算関数 ============
  function updateKPIs() {
    const validationData = tables[validationResultIdx]?.records || [];
    const trustData = tables[trustScoreIdx]?.records || [];

    // 未検証件数
    const unvalidated = validationData.filter(r => r.検証ステータス === '保留' || !r.検証ステータス).length;

    // エラー検出件数（重要度別）
    const errors = validationData.filter(r => r.検証ステータス === '不合格');
    const critical = errors.filter(r => r.重要度 === '致命的').length;
    const high = errors.filter(r => r.重要度 === '高').length;

    // 警告件数
    const warnings = validationData.filter(r => r.検証ステータス === '警告');
    const medium = warnings.filter(r => r.重要度 === '中').length;
    const low = warnings.filter(r => r.重要度 === '低').length;

    // 検証完了件数
    const completed = validationData.filter(r => r.検証ステータス === '合格').length;
    const total = validationData.length || 1;
    const passRate = Math.round((completed / total) * 100);

    container.querySelector('[data-testid="kpi-unvalidated"]').textContent = unvalidated;
    container.querySelector('[data-testid="kpi-errors"]').textContent = errors.length;
    container.querySelector('[data-testid="kpi-errors"]').parentElement.nextElementSibling.textContent = `致命的: ${critical} / 高: ${high}`;
    container.querySelector('[data-testid="kpi-warnings"]').textContent = warnings.length;
    container.querySelector('[data-testid="kpi-warnings"]').parentElement.nextElementSibling.textContent = `中: ${medium} / 低: ${low}`;
    container.querySelector('[data-testid="kpi-completed"]').textContent = completed;
    container.querySelector('[data-testid="kpi-completed"]').parentElement.nextElementSibling.textContent = `合格率: ${passRate}%`;
  }

  // ============ 2. グラフ初期化 ============
  function initCharts() {
    const trustData = tables[trustScoreIdx]?.records || [];
    const validationData = tables[validationResultIdx]?.records || [];

    // 信頼度スコア分布（円グラフ）
    const scoreRanges = {
      '90-100': trustData.filter(r => r.総合スコア >= 90).length,
      '70-89': trustData.filter(r => r.総合スコア >= 70 && r.総合スコア < 90).length,
      '50-69': trustData.filter(r => r.総合スコア >= 50 && r.総合スコア < 70).length,
      '0-49': trustData.filter(r => r.総合スコア < 50).length
    };

    const ctxDist = container.querySelector('#chart-score-dist').getContext('2d');
    new window.Chart(ctxDist, {
      type: 'doughnut',
      data: {
        labels: ['90-100', '70-89', '50-69', '0-49'],
        datasets: [{
          data: [scoreRanges['90-100'], scoreRanges['70-89'], scoreRanges['50-69'], scoreRanges['0-49']],
          backgroundColor: ['#00aa44', '#ffaa00', '#ff6a00', '#ff3333'],
          borderColor: 'var(--bg-card)',
          borderWidth: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { position: 'bottom', labels: { font: { size: 11 }, color: '#9fb0d1', padding: 10 } }
        }
      }
    });

    // エラー重要度別集計（棒グラフ）
    const severityCounts = {
      '致命的': validationData.filter(r => r.重要度 === '致命的').length,
      '高': validationData.filter(r => r.重要度 === '高').length,
      '中': validationData.filter(r => r.重要度 === '中').length,
      '低': validationData.filter(r => r.重要度 === '低').length
    };

    const ctxSev = container.querySelector('#chart-error-severity').getContext('2d');
    new window.Chart(ctxSev, {
      type: 'bar',
      data: {
        labels: ['致命的', '高', '中', '低'],
        datasets: [{
          label: 'エラー件数',
          data: [severityCounts['致命的'], severityCounts['高'], severityCounts['中'], severityCounts['低']],
          backgroundColor: ['#ff3333', '#ff6a00', '#ffaa00', '#ffdd00'],
          borderRadius: 4,
          borderSkipped: false
        }]
      },
      options: {
        indexAxis: 'y',
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false }
        },
        scales: {
          x: { ticks: { color: '#9fb0d1', font: { size: 10 } }, grid: { color: 'rgba(255,255,255,0.05)' } },
          y: { ticks: { color: '#9fb0d1', font: { size: 10 } }, grid: { display: false } }
        }
      }
    });
  }

  // ============ 3. テーブル再描画関数 ============
  function renderDuplicateTable(rows) {
    const tbody = container.querySelector('#duplicate-tbody');
    tbody.innerHTML = (rows || []).slice(0, 5).map(r => `
      <tr style="border-bottom: 1px solid var(--border); cursor: pointer;" onclick="window.showScreen('scr-1781413297335')">
        <td style="padding: 0.5rem; color: var(--text);">${(r.主受注ID || '').substring(0, 8)}...</td>
        <td style="padding: 0.5rem; color: var(--text);">${r.マッチング信頼度 || 0}%</td>
        <td style="padding: 0.5rem;"><span style="background: ${r.検出ステータス === '確認済み' ? '#00aa4433' : '#ffaa0033'}; color: ${r.検出ステータス === '確認済み' ? '#00aa44' : '#ffaa00'}; padding: 0.2rem 0.5rem; border-radius: 3px; font-size: 0.75rem;">${r.検出ステータス || '未確認'}</span></td>
      </tr>
    `).join('');
  }

  function renderConflictTable(rows) {
    const tbody = container.querySelector('#conflict-tbody');
    tbody.innerHTML = (rows || []).slice(0, 5).map(r => `
      <tr style="border-bottom: 1px solid var(--border); cursor: pointer;" onclick="window.showScreen('scr-1781413311177')">
        <td style="padding: 0.5rem; color: var(--text);">${r.矛盾タイプ || '不明'}</td>
        <td style="padding: 0.5rem;"><span style="background: ${r.重要度 === '高' ? '#ff333333' : r.重要度 === '中' ? '#ffaa0033' : '#ffdd0033'}; color: ${r.重要度 === '高' ? '#ff3333' : r.重要度 === '中' ? '#ffaa00' : '#ffdd00'}; padding: 0.2rem 0.5rem; border-radius: 3px; font-size: 0.75rem;">${r.重要度 || '低'}</span></td>
        <td style="padding: 0.5rem; color: var(--text);">${r.ステータス || '未対応'}</td>
      </tr>
    `).join('');
  }

  function renderMissingTable(rows) {
    const tbody = container.querySelector('#missing-tbody');
    tbody.innerHTML = (rows || []).slice(0, 5).map(r => `
      <tr style="border-bottom: 1px solid var(--border); cursor: pointer;" onclick="window.showScreen('scr-1781413340116')">
        <td style="padding: 0.5rem; color: var(--text);">${(r.受注ID || '').substring(0, 8)}...</td>
        <td style="padding: 0.5rem; color: var(--text);">${r.漏れ項目名 || '不明'}</td>
        <td style="padding: 0.5rem;"><span style="background: ${r.重要度 === '高' ? '#ff333333' : r.重要度 === '中' ? '#ffaa0033' : '#ffdd0033'}; color: ${r.重要度 === '高' ? '#ff3333' : r.重要度 === '中' ? '#ffaa00' : '#ffdd00'}; padding: 0.2rem 0.5rem; border-radius: 3px; font-size: 0.75rem;">${r.重要度 || '低'}</span></td>
        <td style="padding: 0.5rem; color: var(--text);">${r.検出ステータス || '未対応'}</td>
      </tr>
    `).join('');
  }

  function renderPriorityTable(rows) {
    const tbody = container.querySelector('#priority-tbody');
    tbody.innerHTML = (rows || []).slice(0, 5).map(r => `
      <tr style="border-bottom: 1px solid var(--border); cursor: pointer;" onclick="window.showScreen('scr-1781413354977')">
        <td style="padding: 0.5rem;"><span style="background: ${r.優先度レベル <= 2 ? '#ff333333' : r.優先度レベル === 3 ? '#ffaa0033' : '#ffdd0033'}; color: ${r.優先度レベル <= 2 ? '#ff3333' : r.優先度レベル === 3 ? '#ffaa00' : '#ffdd00'}; padding: 0.2rem 0.5rem; border-radius: 3px; font-size: 0.75rem; font-weight: 600;">P${r.優先度レベル || 5}</span></td>
        <td style="padding: 0.5rem; color: var(--text);">${r.エラー分類 || '不明'}</td>
        <td style="padding: 0.5rem; color: var(--text);">${r.修正ステータス || '未対応'}</td>
      </tr>
    `).join('');
  }

  // ============ 4. 初期データ読み込みと描画 ============
  async function loadAndRender() {
    try {
      // 各テーブルのデータを取得
      if (validationResultIdx >= 0) {
        const validationData = await window.aivicApi.list(validationResultIdx);
        if (validationData) tables[validationResultIdx].records = validationData;
      }
      if (trustScoreIdx >= 0) {
        const trustData = await window.aivicApi.list(trustScoreIdx);
        if (trustData) tables[trustScoreIdx].records = trustData;
      }
      if (duplicateIdx >= 0) {
        const dupData = await window.aivicApi.list(duplicateIdx);
        if (dupData) tables[duplicateIdx].records = dupData;
        renderDuplicateTable(tables[duplicateIdx].records);
      }
      if (conflictIdx >= 0) {
        const confData = await window.aivicApi.list(conflictIdx);
        if (confData) tables[conflictIdx].records = confData;
        renderConflictTable(tables[conflictIdx].records);
      }
      if (missingIdx >= 0) {
        const missData = await window.aivicApi.list(missingIdx);
        if (missData) tables[missingIdx].records = missData;
        renderMissingTable(tables[missingIdx].records);
      }
      if (priorityIdx >= 0) {
        const prioData = await window.aivicApi.list(priorityIdx);
        if (prioData) tables[priorityIdx].records = prioData;
        renderPriorityTable(tables[priorityIdx].records);
      }

      updateKPIs();
      initCharts();
    } catch (err) {
      console.error('データ読み込みエラー:', err);
      // フォールバック: tables に初期データがあればそれを使う
      if (tables[duplicateIdx]) renderDuplicateTable(tables[duplicateIdx].records);
      if (tables[conflictIdx]) renderConflictTable(tables[conflictIdx].records);
      if (tables[missingIdx]) renderMissingTable(tables[missingIdx].records);
      if (tables[priorityIdx]) renderPriorityTable(tables[priorityIdx].records);
      updateKPIs();
      initCharts();
    }
  }

  // ============ 5. 更新ボタンのイベントリスナー ============
  container.querySelector('[data-testid="btn-refresh"]').addEventListener('click', async () => {
    await loadAndRender();
  });

  // ============ 6. 初期描画 ============
  loadAndRender();
}

function(container, apiUrl, tables) {
  // タブ切り替え機能
  const tabBtns = container.querySelectorAll('.tab-btn');
  const tabContents = {
    'validation': container.querySelector('#tab-validation-content'),
    'edit': container.querySelector('#tab-edit-content'),
    'history': container.querySelector('#tab-history-content')
  };

  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      // 全タブを非アクティブに
      tabBtns.forEach(b => {
        b.style.color = 'var(--text-muted)';
        b.style.borderBottomColor = 'transparent';
      });
      Object.values(tabContents).forEach(content => {
        content.style.display = 'none';
      });

      // クリックされたタブをアクティブに
      const tabName = btn.dataset.testid.replace('tab-', '');
      btn.style.color = 'var(--text)';
      btn.style.borderBottomColor = 'var(--primary)';
      tabContents[tabName].style.display = 'block';
    });
  });

  // 修正を保存ボタン
  const saveBtn = container.querySelector('[data-testid="save-button"]');
  saveBtn.addEventListener('click', async () => {
    const quantity = container.querySelector('[data-testid="edit-quantity"]').value;
    const amount = container.querySelector('[data-testid="edit-amount"]').value;
    const address = container.querySelector('[data-testid="edit-address"]').value;
    const phone = container.querySelector('[data-testid="edit-phone"]').value;
    const email = container.querySelector('[data-testid="edit-email"]').value;
    const reason = container.querySelector('[data-testid="edit-reason"]').value;
    const notes = container.querySelector('[data-testid="edit-notes"]').value;

    if (!reason) {
      alert('修正理由を選択してください');
      return;
    }

    // 修正履歴テーブルに保存（tableIndex: 修正履歴テーブルのインデックス）
    const result = await window.aivicApi.save(1, {
      order_id: 'ORD-2024-001234',
      修正項目名: '複数項目',
      修正前値: JSON.stringify({ quantity: 3, email: 'contact@sample' }),
      修正後値: JSON.stringify({ quantity, amount, address, phone, email }),
      修正理由: reason,
      修正備考: notes,
      修正ユーザーID: 'user-001',
      修正日時: new Date().toISOString()
    });

    if (result) {
      alert('修正を保存しました');
      // 修正フォームをリセット
      container.querySelector('[data-testid="edit-reason"]').value = '';
      container.querySelector('[data-testid="edit-notes"]').value = '';
    }
  });

  // キャンセルボタン
  const cancelBtn = container.querySelector('[data-testid="cancel-button"]');
  cancelBtn.addEventListener('click', () => {
    container.querySelector('[data-testid="edit-quantity"]').value = '5';
    container.querySelector('[data-testid="edit-amount"]').value = '60000';
    container.querySelector('[data-testid="edit-address"]').value = '東京都渋谷区道玄坂 1-2-3 ビジネスビル 5F';
    container.querySelector('[data-testid="edit-phone"]').value = '';
    container.querySelector('[data-testid="edit-email"]').value = 'contact@sample.co.jp';
    container.querySelector('[data-testid="edit-reason"]').value = '';
    container.querySelector('[data-testid="edit-notes"]').value = '';
  });

  // 承認して確定ボタン
  const approveBtn = container.querySelector('[data-testid="approve-button"]');
  approveBtn.addEventListener('click', async () => {
    if (!confirm('この受注データを承認して確定しますか？')) {
      return;
    }

    // 連携承認フロー更新（tableIndex: 連携承認フロー）
    const result = await window.aivicApi.update(7, 'flow-001', {
      現在ステータス: '承認済',
      承認判定: '承認',
      承認コメント: 'データ品質確認完了。修正内容を確認し承認します。',
      承認日時: new Date().toISOString()
    });

    if (result) {
      alert('受注データを承認・確定しました');
      // 受注検証ダッシュボードへ遷移
      window.showScreen('scr-1781413262699');
    }
  });

  // 戻るボタン
  const backBtn = container.querySelector('[data-testid="back-button"]');
  backBtn.addEventListener('click', () => {
    window.showScreen('scr-1781413262699');
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#duplicate-tbody");
  const filterCustomer = container.querySelector("#filter-customer");
  const filterDateFrom = container.querySelector("#filter-date-from");
  const filterDateTo = container.querySelector("#filter-date-to");
  const filterChannel = container.querySelector("#filter-channel");
  const btnSearch = container.querySelector("#btn-search");
  const btnExport = container.querySelector("#btn-export");
  const comparisonPanel = container.querySelector("#comparison-panel");
  const btnCloseComparison = container.querySelector("#btn-close-comparison");
  const btnConfirmDuplicate = container.querySelector("#btn-confirm-duplicate");
  const btnMergeDuplicate = container.querySelector("#btn-merge-duplicate");
  const btnRejectDuplicate = container.querySelector("#btn-reject-duplicate");
  const comparisonMain = container.querySelector("#comparison-main");
  const comparisonSub = container.querySelector("#comparison-sub");
  const comparisonSummary = container.querySelector("#comparison-summary");

  let allDuplicates = [];
  let selectedDuplicate = null;

  // 1. 重複受注一覧を再描画
  function renderDuplicates(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-card);"><td colspan="7" style="padding: 12px; text-align: center; color: var(--text-muted);">重複受注が見つかりません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => {
      const scorePercent = Math.min(100, Math.max(0, r.マッチング信頼度 || 0));
      const statusColor = r.検出ステータス === '確認済み' ? '#4caf50' : r.検出ステータス === '統合済み' ? '#2196f3' : '#ff9800';
      return `
        <tr data-id="${r.重複受注検出結果ID}" style="background: var(--bg-card); border-bottom: 1px solid var(--border); hover-bg: var(--bg-main);">
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">${(r.主受注ID || '').substring(0, 8)}</td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">${(r.副受注ID || '').substring(0, 8)}</td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">${r.顧客名 || '-'}</td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">${r.チャネル || '-'}</td>
          <td style="padding: 8px 12px; text-align: center;">
            <div style="display: flex; align-items: center; gap: 6px; justify-content: center;">
              <div style="width: 60px; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden;">
                <div style="width: ${scorePercent}%; height: 100%; background: var(--primary); transition: width 0.2s;"></div>
              </div>
              <span style="color: var(--text); font-size: 11px; font-weight: 600;">${scorePercent}%</span>
            </div>
          </td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">
            <span style="display: inline-block; padding: 2px 6px; background: ${statusColor}; color: #fff; border-radius: 3px; font-size: 10px; font-weight: 500;">${r.検出ステータス || '未確認'}</span>
          </td>
          <td style="padding: 8px 12px; text-align: center;">
            <button class="compare-btn action-btn secondary" data-id="${r.重複受注検出結果ID}" style="padding: 4px 8px; font-size: 11px;">比較</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データを描画
  renderDuplicates(tables[0]?.records || []);
  allDuplicates = tables[0]?.records || [];

  // 3. 検索ボタン
  btnSearch.addEventListener("click", async () => {
    const keyword = filterCustomer.value.toLowerCase();
    const dateFrom = filterDateFrom.value ? new Date(filterDateFrom.value) : null;
    const dateTo = filterDateTo.value ? new Date(filterDateTo.value) : null;
    const channel = filterChannel.value;

    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    allDuplicates = rows.filter(r => {
      const matchCustomer = !keyword || (r.顧客名 || '').toLowerCase().includes(keyword);
      const matchChannel = !channel || r.チャネル === channel;
      const matchDate = true; // 簡略化：日付フィルターは後で実装可
      return matchCustomer && matchChannel && matchDate;
    });

    renderDuplicates(allDuplicates);
  });

  // 4. CSV出力
  btnExport.addEventListener("click", () => {
    if (!allDuplicates || allDuplicates.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }
    const headers = ["主受注ID", "副受注ID", "顧客名", "チャネル", "マッチング信頼度", "検出ステータス", "マッチング理由"];
    const rows = allDuplicates.map(r => [
      r.主受注ID || '',
      r.副受注ID || '',
      r.顧客名 || '',
      r.チャネル || '',
      r.マッチング信頼度 || '',
      r.検出ステータス || '',
      r.マッチング理由 || ''
    ]);
    const csv = "\uFEFF" + [headers, ...rows].map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "duplicate-orders.csv";
    link.click();
  });

  // 5. 比較ボタン（イベントデリゲーション）
  container.addEventListener("click", async e => {
    const compareBtn = e.target.closest(".compare-btn");
    if (compareBtn) {
      const duplicateId = compareBtn.dataset.id;
      selectedDuplicate = allDuplicates.find(d => d.重複受注検出結果ID === duplicateId);
      if (!selectedDuplicate) return;

      // 詳細データを取得（簡略化：ここではサンプルデータを使用）
      const mainOrderId = selectedDuplicate.主受注ID;
      const subOrderId = selectedDuplicate.副受注ID;

      // 主受注の詳細を表示
      comparisonMain.innerHTML = `
        <div style="margin-bottom: 8px;"><strong>受注ID:</strong> ${mainOrderId}</div>
        <div style="margin-bottom: 8px;"><strong>顧客名:</strong> ${selectedDuplicate.顧客名}</div>
        <div style="margin-bottom: 8px;"><strong>受注日時:</strong> 2024-01-15 10:30</div>
        <div style="margin-bottom: 8px;"><strong>金額:</strong> ¥125,000</div>
        <div style="margin-bottom: 8px;"><strong>チャネル:</strong> ${selectedDuplicate.チャネル}</div>
        <div style="margin-bottom: 8px;"><strong>ステータス:</strong> <span style="color: #4caf50;">確認済</span></div>
      `;

      // 副受注の詳細を表示
      comparisonSub.innerHTML = `
        <div style="margin-bottom: 8px;"><strong>受注ID:</strong> ${subOrderId}</div>
        <div style="margin-bottom: 8px;"><strong>顧客名:</strong> ${selectedDuplicate.顧客名}</div>
        <div style="margin-bottom: 8px;"><strong>受注日時:</strong> 2024-01-15 10:32</div>
        <div style="margin-bottom: 8px;"><strong>金額:</strong> <span style="color: #ff6a00;">¥125,500</span></div>
        <div style="margin-bottom: 8px;"><strong>チャネル:</strong> Web注文</div>
        <div style="margin-bottom: 8px;"><strong>ステータス:</strong> <span style="color: #ff9800;">未確認</span></div>
      `;

      // マッチング詳細
      comparisonSummary.innerHTML = `
        <div style="margin-bottom: 6px;"><strong>マッチング信頼度:</strong> ${selectedDuplicate.マッチング信頼度}%</div>
        <div style="margin-bottom: 6px;"><strong>マッチング理由:</strong> ${selectedDuplicate.マッチング理由}</div>
        <div style="margin-bottom: 6px;"><strong>差分項目:</strong> 金額（¥500差）、受注時刻（2分差）</div>
        <div><strong>推奨対応:</strong> 統合処理（同一顧客の重複受注と判定）</div>
      `;

      comparisonPanel.style.display = "block";
    }
  });

  // 6. 比較パネルを閉じる
  btnCloseComparison.addEventListener("click", () => {
    comparisonPanel.style.display = "none";
    selectedDuplicate = null;
  });

  // 7. 重複確認ボタン
  btnConfirmDuplicate.addEventListener("click", async () => {
    if (!selectedDuplicate) return;
    const updated = await window.aivicApi.update(0, selectedDuplicate.重複受注検出結果ID, {
      検出ステータス: "確認済み"
    });
    if (updated) {
      alert("重複受注を確認しました");
      selectedDuplicate.検出ステータス = "確認済み";
      renderDuplicates(allDuplicates);
      comparisonPanel.style.display = "none";
    }
  });

  // 8. 統合処理へボタン
  btnMergeDuplicate.addEventListener("click", () => {
    if (!selectedDuplicate) return;
    // 統合処理画面へ遷移
    window.showScreen("scr-1781413550629");
  });

  // 9. 誤検出ボタン
  btnRejectDuplicate.addEventListener("click", async () => {
    if (!selectedDuplicate) return;
    if (!confirm("この重複検出を誤検出として却下しますか？")) return;
    const updated = await window.aivicApi.update(0, selectedDuplicate.重複受注検出結果ID, {
      検出ステータス: "誤検出"
    });
    if (updated) {
      alert("誤検出として記録しました");
      selectedDuplicate.検出ステータス = "誤検出";
      renderDuplicates(allDuplicates);
      comparisonPanel.style.display = "none";
    }
  });
}

function(container, apiUrl, tables) {
