    const colors = {
      "高": "#ff6a6a",
      "中": "#ffa500",
      "低": "#4ade80"
    };
    return `<span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${colors[severity] || '#999'}20; color: ${colors[severity] || '#999'}; font-size: 11px; font-weight: 600;">${severity}</span>`;
  }

  function getStatusBadge(status) {
    const colors = {
      "未対応": "#999",
      "対応中": "#ffa500",
      "完了": "#4ade80"
    };
    return `<span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${colors[status] || '#999'}20; color: ${colors[status] || '#999'}; font-size: 11px; font-weight: 600;">${status}</span>`;
  }

  // 一覧再描画
  function renderRows(rows) {
    listTbody.innerHTML = rows.map(r => {
      const detectedAt = r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : "—";
      return `
        <tr data-id="${r.入力漏れ検出結果ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background=''">
          <td style="padding: 8px 12px; color: var(--text);">${r.受注ID || "—"}</td>
          <td style="padding: 8px 12px; color: var(--text);">${r.漏れ項目名 || "—"}</td>
          <td style="padding: 8px 12px;">${getSeverityBadge(r.重要度)}</td>
          <td style="padding: 8px 12px;">${getStatusBadge(r.検出ステータス)}</td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-size: 12px;">${detectedAt}</td>
          <td style="padding: 8px 12px; text-align: center; color: var(--text);">${r.信頼度スコア || "—"}</td>
        </tr>
