        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px; text-transform: uppercase; letter-spacing: 0.5px;">項目区分</div>
        <div style="font-size: 13px; color: var(--text);">${record.漏れ項目区分 || "—"}</div>
      </div>

