    } else {
      ocrSuggestion.style.display = "none";
    }
  }

  // 初期データ描画
  window.aivicApi.list(0).then(rows => {
    allRecords = rows || [];
    renderRows(allRecords);
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const orderId = container.querySelector("#filter-order-id").value.toLowerCase();
    const severity = container.querySelector("#filter-severity").value;
    const status = container.querySelector("#filter-status").value;

    const filtered = allRecords.filter(r => {
      const matchOrder = !orderId || (r.受注ID && r.受注ID.toLowerCase().includes(orderId));
      const matchSeverity = !severity || r.重要度 === severity;
      const matchStatus = !status || r.検出ステータス === status;
      return matchOrder && matchSeverity && matchStatus;
    });

    renderRows(filtered);
  });

  // 行クリックで詳細表示
  container.addEventListener("click", e => {
    const tr = e.target.closest("tbody tr");
    if (tr) {
      showDetail(tr.dataset.id);
    }
  });

  // AI_OCR提案を採用
  container.querySelector("#btn-adopt-ocr").addEventListener("click", () => {
    const suggestedValue = "サンプル提案値"; // 実際には ocrValue から抽出
    container.querySelector("#input-correction-value").value = suggestedValue;
  });

  // 修正を保存
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    if (!currentSelectedId) return;

    const correctionValue = container.querySelector("#input-correction-value").value.trim();
    const correctionReason = container.querySelector("#input-correction-reason").value;
    const correctionNote = container.querySelector("#input-correction-note").value.trim();

    if (!correctionValue || !correctionReason) {
      alert("修正値と修正理由を入力してください");
      return;
    }

    // 修正履歴を保存（テーブルインデックス 1 を想定）
    const saved = await window.aivicApi.save(1, {
      受注データID: currentSelectedId,
      修正項目名: allRecords.find(r => r.入力漏れ検出結果ID === currentSelectedId)?.漏れ項目名,
      修正前値: "",
      修正後値: correctionValue,
      修正理由: correctionReason,
      修正備考: correctionNote,
      修正ユーザーID: "current-user-id",
      修正日時: new Date().toISOString()
    });

    if (saved) {
      alert("修正を保存しました");
      // 入力漏れ検出結果を更新
      await window.aivicApi.update(0, currentSelectedId, {
        修正済みフラグ: true,
        修正日時: new Date().toISOString(),
        検出ステータス: "完了"
      });
      window.aivicApi.list(0).then(rows => {
        allRecords = rows || [];
        renderRows(allRecords);
        showDetail(currentSelectedId);
      });
    }
  });

  // キャンセル
  container.querySelector("#btn-cancel-edit").addEventListener("click", () => {
    editFormSection.style.display = "none";
    detailContent.style.display = "none";
    detailEmpty.style.display = "block";
    currentSelectedId = null;
  });

  // CSV出力
  container.querySelector("#btn-export").addEventListener("click", () => {
    if (allRecords.length === 0) {
      alert("出力するデータがありません");
      return;
    }

    const headers = ["受注ID", "漏れ項目名", "項目区分", "重要度", "対応状況", "検出ルール", "検出日時", "修正済み", "備考"];
    const rows = allRecords.map(r => [
      r.受注ID || "",
      r.漏れ項目名 || "",
      r.漏れ項目区分 || "",
      r.重要度 || "",
      r.検出ステータス || "",
      r.検出ルール || "",
      r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP') : "",
      r.修正済みフラグ ? "○" : "×",
      r.備考 || ""
    ]);

    const csv = "\uFEFF" + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(",")
    ).join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `入力漏れ検出結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });
}

