      const priorityColor = r.優先度レベル === 1 ? "#ff3333" : r.優先度レベル === 2 ? "#ff6a00" : r.優先度レベル === 3 ? "#ffc107" : "#4caf50";
      const statusBg = r.修正ステータス === "完了" ? "rgba(76,175,80,0.15)" : r.修正ステータス === "対応中" ? "rgba(255,193,7,0.15)" : r.修正ステータス === "未対応" ? "rgba(255,106,0,0.15)" : "rgba(100,100,100,0.15)";
      const statusColor = r.修正ステータス === "完了" ? "#4caf50" : r.修正ステータス === "対応中" ? "#ffc107" : r.修正ステータス === "未対応" ? "#ff6a00" : "#999";
      const confidenceScore = r.信頼度スコア || 0;
      const confidenceColor = confidenceScore >= 80 ? "#4caf50" : confidenceScore >= 60 ? "#ffc107" : "#ff6a00";

      return `<tr data-id="${r.優先度リストID || ""}" style="border-bottom: 1px solid rgba(255,255,255,0.04); hover: background: rgba(255,255,255,0.02);">
        <td style="padding: 8px 12px; color: var(--text);">${r.受注データID ? r.受注データID.substring(0, 8) : "-"}</td>
        <td style="padding: 8px 12px; color: var(--text);">${r.チャネル || "-"}</td>
        <td style="padding: 8px 12px; color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.エラー内容 || ""}">${r.エラー内容 || "-"}</td>
        <td style="padding: 8px 12px; text-align: center;"><span style="background: ${priorityColor}; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px; font-weight: 600;">${priorityLabel}</span></td>
        <td style="padding: 8px 12px; text-align: center; color: ${confidenceColor}; font-weight: 600;">${confidenceScore}%</td>
        <td style="padding: 8px 12px; color: var(--text-muted); font-size: 11px;">${r.検出日時 ? new Date(r.検出日時).toLocaleString("ja-JP", {year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"}) : "-"}</td>
        <td style="padding: 8px 12px;"><span style="background: ${statusBg}; color: ${statusColor}; padding: 2px 6px; border-radius: 3px; font-size: 11px; font-weight: 600;">${r.修正ステータス || "未対応"}</span></td>
        <td style="padding: 8px 12px; text-align: center; display: flex; gap: 4px; justify-content: center;">
          <button class="action-btn secondary detail-btn" data-id="${r.優先度リストID || ""}" style="padding: 3px 8px; font-size: 11px;">詳細</button>
          <button class="action-btn secondary edit-btn" data-id="${r.優先度リストID || ""}" style="padding: 3px 8px; font-size: 11px;">修正</button>
        </td>
      </tr>`;
    }).join("");

    recordCountEl.textContent = rows.length;
    totalCountEl.textContent = allRows.length;

    // ステータス集計
    const pending = rows.filter(r => r.修正ステータス === "未対応").length;
    const inProgress = rows.filter(r => r.修正ステータス === "対応中").length;
    const completed = rows.filter(r => r.修正ステータス === "完了").length;
    countPendingEl.textContent = pending;
    countInProgressEl.textContent = inProgress;
    countCompletedEl.textContent = completed;
  }

  // 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (!rows || rows.length === 0) {
      // サンプルデータ
      rows = [
        {
          優先度リストID: "uuid-001",
          受注データID: "order-20250523-001",
          チャネル: "Web注文",
          エラー内容: "顧客名が入力漏れ",
          優先度レベル: 1,
          信頼度スコア: 95,
          検出日時: new Date(Date.now() - 3600000).toISOString(),
          修正ステータス: "未対応",
          エラー分類: "入力漏れ"
        },
        {
          優先度リストID: "uuid-002",
          受注データID: "order-20250523-002",
          チャネル: "電話受注",
          エラー内容: "受注金額が重複受注と矛盾",
          優先度レベル: 2,
          信頼度スコア: 88,
          検出日時: new Date(Date.now() - 7200000).toISOString(),
          修正ステータス: "対応中",
          エラー分類: "チャネル矛盾"
        },
        {
          優先度リストID: "uuid-003",
          受注データID: "order-20250523-003",
          チャネル: "店舗POS",
          エラー内容: "OCR認識で配送先住所が誤認識",
          優先度レベル: 2,
          信頼度スコア: 72,
          検出日時: new Date(Date.now() - 10800000).toISOString(),
          修正ステータス: "未対応",
          エラー分類: "OCR誤認識"
        },
        {
          優先度リストID: "uuid-004",
          受注データID: "order-20250523-004",
          チャネル: "API連携",
          エラー内容: "重複受注として検出（同一顧客・同一商品）",
          優先度レベル: 3,
          信頼度スコア: 85,
          検出日時: new Date(Date.now() - 14400000).toISOString(),
          修正ステータス: "完了",
          エラー分類: "重複受注"
        },
        {
          優先度リストID: "uuid-005",
          受注データID: "order-20250523-005",
          チャネル: "Web注文",
          エラー内容: "電話番号の形式が不正",
          優先度レベル: 3,
          信頼度スコア: 78,
          検出日時: new Date(Date.now() - 18000000).toISOString(),
          修正ステータス: "未対応",
          エラー分類: "入力漏れ"
        }
      ];
    }
    allRows = rows;
    renderRows(rows);
  });

  // 検索・フィルタ処理
  function applyFilters() {
    const priority = priorityFilter.value;
    const errorType = errorTypeFilter.value;
    const status = statusFilter.value;
    const confidence = confidenceFilter.value;

    let filtered = allRows.filter(r => {
      if (priority && r.優先度レベル !== parseInt(priority)) return false;
      if (errorType && r.エラー分類 !== errorType) return false;
      if (status && r.修正ステータス !== status) return false;
      if (confidence) {
        const score = r.信頼度スコア || 0;
        const [min, max] = confidence.split("-").map(Number);
        if (score < min || score > max) return false;
      }
      return true;
    });

    renderRows(filtered);
  }

  searchBtn.addEventListener("click", applyFilters);
  priorityFilter.addEventListener("change", applyFilters);
  errorTypeFilter.addEventListener("change", applyFilters);
  statusFilter.addEventListener("change", applyFilters);
  confidenceFilter.addEventListener("change", applyFilters);

  // CSVエクスポート
  exportBtn.addEventListener("click", () => {
    const headers = ["受注ID", "チャネル", "エラー内容", "優先度", "信頼度スコア", "検出日時", "修正状態"];
    const rows = Array.from(tbody.querySelectorAll("tr")).map(tr => {
      const cells = tr.querySelectorAll("td");
      return [
        cells[0]?.textContent || "",
        cells[1]?.textContent || "",
        cells[2]?.textContent || "",
        cells[3]?.textContent || "",
        cells[4]?.textContent || "",
        cells[5]?.textContent || "",
        cells[6]?.textContent || ""
      ];
    });

    const csv = "\uFEFF" + [headers, ...rows].map(r => r.map(c => `"${c.replace(/"/g, '""')}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "priority-list-" + new Date().toISOString().split("T")[0] + ".csv";
    link.click();
  });

  // 行レベル操作（詳細・修正）
  container.addEventListener("click", async e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const row = allRows.find(r => r.優先度リストID === id);
      if (row) {
        // 詳細画面へ遷移（受注データ詳細確認・修正画面）
        window.showScreen("scr-1781413282852");
      }
      return;
    }

    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const id = editBtn.dataset.id;
      const row = allRows.find(r => r.優先度リストID === id);
      if (row) {
        // 修正画面へ遷移
        window.showScreen("scr-1781413686599");
      }
      return;
    }
  });
}

function(container, apiUrl, tables) {
  const ITEMS_PER_PAGE = 15;
  let currentPage = 1;
  let allResults = [];
  let filteredResults = [];

  // ========== 1. 再描画関数 ==========
  function renderRows(rows) {
    const tbody = container.querySelector("#result-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; padding: 2rem; color: var(--text-muted);">検証結果がありません</td></tr>';
      return;
    }

    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    const end = start + ITEMS_PER_PAGE;
    const pageRows = rows.slice(start, end);

    tbody.innerHTML = pageRows.map(r => {
      const statusColor = r.検証ステータス === '合格' ? '#4CAF50' : 
                          r.検証ステータス === '不合格' ? '#ff6a00' : 
                          r.検証ステータス === '警告' ? '#FFC107' : '#9fb0d1';

      const priorityColor = r.修正優先度 === '1' ? '#ff6a00' : 
                            r.修正優先度 === '2' ? '#FFC107' : '#4CAF50';

      return `<tr style="border-bottom: 1px solid var(--border); cursor: pointer;" data-id="${r.検証結果ID || r.id}">
        <td style="padding: 0.75rem; color: var(--text);">${r.受注データID || '--'}</td>
        <td style="padding: 0.75rem; color: var(--text);">${r.チャネル名 || '--'}</td>
        <td style="padding: 0.75rem;">
          <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 3px; background: ${statusColor}20; color: ${statusColor}; font-size: 0.85rem; font-weight: 500;">
            ${r.検証ステータス || '--'}
          </span>
        </td>
        <td style="padding: 0.75rem; text-align: center; color: var(--text);">${r.総合スコア || r.信頼度スコア || '--'}</td>
        <td style="padding: 0.75rem; color: var(--text); font-size: 0.85rem;">${(r.エラーメッセージ || r.検出エラー内容 || '--').substring(0, 40)}</td>
        <td style="padding: 0.75rem;">
          <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 3px; background: ${r.重要度 === '致命的' ? '#ff6a0020' : r.重要度 === '高' ? '#FFC10720' : '#4CAF5020'}; color: ${r.重要度 === '致命的' ? '#ff6a00' : r.重要度 === '高' ? '#FFC107' : '#4CAF50'}; font-size: 0.85rem;">
            ${r.重要度 || '--'}
          </span>
        </td>
        <td style="padding: 0.75rem;">
          <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 3px; background: ${priorityColor}20; color: ${priorityColor}; font-size: 0.85rem; font-weight: 600;">
            P${r.修正優先度 || '--'}
          </span>
        </td>
        <td style="padding: 0.75rem; text-align: center;">
          <button class="action-btn secondary detail-btn" data-id="${r.検証結果ID || r.id}" style="padding: 0.35rem 0.75rem; font-size: 0.8rem;">
            詳細
          </button>
        </td>
      </tr>`;
    }).join("");

    updatePagination(rows.length);
  }

  function updatePagination(totalRows) {
    const totalPages = Math.ceil(totalRows / ITEMS_PER_PAGE);
    const pageInfo = container.querySelector("#page-info");
    pageInfo.textContent = `ページ ${currentPage} / ${totalPages}`;

    container.querySelector("#btn-prev-page").disabled = currentPage === 1;
    container.querySelector("#btn-next-page").disabled = currentPage >= totalPages;
  }

  // ========== 2. KPI と集計表の更新 ==========
  function updateKPIs(rows) {
    if (!rows || rows.length === 0) {
      container.querySelector("[data-testid='kpi-error-count']").textContent = "0";
      container.querySelector("[data-testid='kpi-pass-rate']").textContent = "0%";
      container.querySelector("[data-testid='kpi-warning-count']").textContent = "0";
      return;
    }

    const errorCount = rows.filter(r => r.検証ステータス === '不合格').length;
    const passCount = rows.filter(r => r.検証ステータス === '合格').length;
    const warningCount = rows.filter(r => r.検証ステータス === '警告').length;
    const passRate = rows.length > 0 ? Math.round((passCount / rows.length) * 100) : 0;

    container.querySelector("[data-testid='kpi-error-count']").textContent = errorCount;
    container.querySelector("[data-testid='kpi-pass-rate']").textContent = passRate + "%";
    container.querySelector("[data-testid='kpi-warning-count']").textContent = warningCount;

    // ステータス集計表
    const statusSummary = {};
    rows.forEach(r => {
      const status = r.検証ステータス || '不明';
      statusSummary[status] = (statusSummary[status] || 0) + 1;
    });

    const tbody = container.querySelector("#status-summary-tbody");
    tbody.innerHTML = Object.entries(statusSummary).map(([status, count]) => {
      const ratio = ((count / rows.length) * 100).toFixed(1);
      return `<tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 0.5rem 0; color: var(--text);">${status}</td>
        <td style="padding: 0.5rem 0; text-align: right; color: var(--text);">${count}</td>
        <td style="padding: 0.5rem 0; text-align: right; color: var(--text-muted);">${ratio}%</td>
      </tr>`;
    }).join("");
  }

  // ========== 3. グラフ描画（信頼度スコア分布） ==========
  function drawConfidenceChart(rows) {
    const canvas = container.querySelector("#confidence-chart");
    const ctx = canvas.getContext("2d");

    // スコア分布を集計（0-20, 20-40, 40-60, 60-80, 80-100）
    const bins = [0, 0, 0, 0, 0];
    rows.forEach(r => {
      const score = parseInt(r.総合スコア || r.信頼度スコア || 0);
      if (score < 20) bins[0]++;
      else if (score < 40) bins[1]++;
      else if (score < 60) bins[2]++;
      else if (score < 80) bins[3]++;
      else bins[4]++;
    });

    const maxBin = Math.max(...bins, 1);
    const barWidth = canvas.width / 5;
    const barSpacing = 8;
    const colors = ['#ff6a00', '#FFC107', '#9fb0d1', '#4CAF50', '#2196F3'];

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';

    bins.forEach((count, i) => {
      const barHeight = (count / maxBin) * (canvas.height - 40);
      const x = i * barWidth + barSpacing;
      const y = canvas.height - 30 - barHeight;

      ctx.fillStyle = colors[i];
      ctx.fillRect(x, y, barWidth - barSpacing * 2, barHeight);

      ctx.fillStyle = '#9fb0d1';
      ctx.fillText(count, x + (barWidth - barSpacing * 2) / 2, canvas.height - 10);
      ctx.fillText(['0-20', '20-40', '40-60', '60-80', '80-100'][i], x + (barWidth - barSpacing * 2) / 2, canvas.height - 20);
    });
  }

  // ========== 4. 初期データ読み込み ==========
  async function loadInitialData() {
    const rows = await window.aivicApi.list(0);
    if (rows) {
      allResults = rows;
      filteredResults = rows;
      renderRows(filteredResults);
      updateKPIs(filteredResults);
      drawConfidenceChart(filteredResults);
    }
  }

  // ========== 5. 検索ボタン ==========
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const channel = container.querySelector("#filter-channel").value;
    const status = container.querySelector("#filter-status").value;

    filteredResults = allResults.filter(r => {
      let match = true;

      if (dateFrom) {
        const execDate = new Date(r.検証実行日時 || r.作成日時 || "");
        if (execDate < new Date(dateFrom)) match = false;
      }

      if (dateTo) {
        const execDate = new Date(r.検証実行日時 || r.作成日時 || "");
        if (execDate > new Date(dateTo + "T23:59:59")) match = false;
      }

      if (channel && r.チャネル名 !== channel && r.チャネルコード !== channel) match = false;
      if (status && r.検証ステータス !== status) match = false;

      return match;
    });

    currentPage = 1;
    renderRows(filteredResults);
    updateKPIs(filteredResults);
    drawConfidenceChart(filteredResults);
  });

  // ========== 6. CSV エクスポート ==========
  container.querySelector("#btn-export").addEventListener("click", async () => {
    if (filteredResults.length === 0) {
      alert("エクスポート対象のデータがありません");
      return;
    }

    const headers = ["受注ID", "チャネル", "検証ステータス", "信頼度スコア", "エラー内容", "重要度", "修正優先度", "検証実行日時"];
    const rows = filteredResults.map(r => [
      r.受注データID || "",
      r.チャネル名 || "",
      r.検証ステータス || "",
      r.総合スコア || r.信頼度スコア || "",
      r.エラーメッセージ || r.検出エラー内容 || "",
      r.重要度 || "",
      r.修正優先度 || "",
      r.検証実行日時 || r.作成日時 || ""
    ]);

    const csv = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...rows.map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `validation_report_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // ========== 7. ページネーション ==========
  container.querySelector("#btn-prev-page").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredResults);
    }
  });

  container.querySelector("#btn-next-page").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredResults.length / ITEMS_PER_PAGE);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredResults);
    }
  });

  // ========== 8. 詳細ボタン（行クリック） ==========
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const resultId = detailBtn.dataset.id;
      const result = filteredResults.find(r => r.検証結果ID === resultId || r.id === resultId);
      if (result) {
        // 詳細確認・修正画面へ遷移
        window.showScreen("scr-1781413282852");
      }
    }
  });

  // ========== 9. 初期化 ==========
  loadInitialData();
}

function(container, apiUrl, tables) {
  // ============================================
  // 1. 要素参照の取得
  // ============================================
  const btnPlayGuidance = container.querySelector("#btn-play-guidance");
  const btnPauseGuidance = container.querySelector("#btn-pause-guidance");
  const volumeSlider = container.querySelector("#volume-slider");
  const volumeDisplay = container.querySelector("#volume-display");
  const btnCamera = container.querySelector("#btn-camera");
  const btnScanner = container.querySelector("#btn-scanner");
  const btnStartOcr = container.querySelector("#btn-start-ocr");
  const btnConfirmData = container.querySelector("#btn-confirm-data");
  const btnRetryOcr = container.querySelector("#btn-retry-ocr");
  const btnGotoDashboard = container.querySelector("#btn-goto-dashboard");
  const fileInput = container.querySelector("#file-input");
  const imagePreview = container.querySelector("#image-preview");
  const ocrProgressBar = container.querySelector("#ocr-progress-bar");
  const ocrProgressText = container.querySelector("#ocr-progress-text");
  const ocrStatus = container.querySelector("#ocr-status");
  const guidanceText = container.querySelector("#guidance-text");
  const lastCaptureTime = container.querySelector("#last-capture-time");
  const extractedDataForm = container.querySelector("#extracted-data-form");
  const extractedItemsList = container.querySelector("#extracted-items-list");
  const scoreOverall = container.querySelector("#score-overall");
  const scoreAccuracy = container.querySelector("#score-accuracy");
  const scoreCompleteness = container.querySelector("#score-completeness");
  const scoreConsistency = container.querySelector("#score-consistency");
  const warningFlag = container.querySelector("#warning-flag");

  // ============================================
  // 2. 状態管理
  // ============================================
  let currentStep = 2;
  let totalSteps = 5;
  let capturedImage = null;
  let extractedData = {};
  let confidenceScores = {};
  let isProcessing = false;

  // ガイダンス内容（ステップ別）
  const guidanceSteps = [
    "受注情報の取込を開始します。カメラまたはスキャナを準備してください。",
    "顧客名を確認してください。カメラを顧客名欄に向けてください。",
    "受注金額を確認してください。金額欄をスキャンしてください。",
    "配送先住所を確認してください。住所欄をスキャンしてください。",
    "すべての情報が正確に取込されたか確認してください。"
  ];

  // ============================================
  // 3. 音声ガイダンス制御
  // ============================================
  function updateGuidanceDisplay() {
    guidanceText.textContent = guidanceSteps[currentStep - 1] || "ガイダンス完了";
    container.querySelector(".card").querySelector("div:first-child").textContent = `ステップ ${currentStep}/${totalSteps}`;
  }

  btnPlayGuidance.addEventListener("click", () => {
    ocrStatus.textContent = "ガイダンス再生中...";
    // 実際の音声再生はここで実装（Web Audio API / HTMLAudioElement）
    setTimeout(() => {
      ocrStatus.textContent = "ガイダンス再生完了";
    }, 2000);
  });

  btnPauseGuidance.addEventListener("click", () => {
    ocrStatus.textContent = "ガイダンス一時停止";
  });

  volumeSlider.addEventListener("input", (e) => {
    const vol = e.target.value;
    volumeDisplay.textContent = vol + "%";
  });

  // ============================================
  // 4. カメラ/スキャナ操作
  // ============================================
  btnCamera.addEventListener("click", () => {
    fileInput.accept = "image/*";
    fileInput.click();
  });

  btnScanner.addEventListener("click", () => {
    fileInput.accept = "image/*";
    fileInput.click();
  });

  fileInput.addEventListener("change", (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      capturedImage = event.target.result;
      imagePreview.innerHTML = `<img src="${capturedImage}" style="max-width: 100%; max-height: 100%; object-fit: contain; border-radius: 4px;">`;
      lastCaptureTime.textContent = new Date().toLocaleTimeString("ja-JP");
      currentStep = Math.min(currentStep + 1, totalSteps);
      updateGuidanceDisplay();
    };
    reader.readAsDataURL(file);
  });

  // ============================================
  // 5. OCR処理シミュレーション
  // ============================================
  btnStartOcr.addEventListener("click", async () => {
    if (!capturedImage) {
      alert("先に画像を撮影またはアップロードしてください");
      return;
    }

    if (isProcessing) return;
    isProcessing = true;
    ocrStatus.textContent = "OCR処理中...";
    btnStartOcr.disabled = true;

    // 進捗バーアニメーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 30;
      if (progress > 100) progress = 100;
      ocrProgressBar.style.width = progress + "%";
      ocrProgressText.textContent = Math.floor(progress) + "%";

      if (progress >= 100) {
        clearInterval(progressInterval);
      }
    }, 300);

    // OCR結果をシミュレート（実際はAPI呼び出し）
    await new Promise(resolve => setTimeout(resolve, 3000));

    extractedData = {
      customer_name: "株式会社サンプル",
      order_amount: "¥150,000",
      shipping_address: "東京都渋谷区道玄坂1-2-3",
      order_date: "2025-01-15",
      contact_phone: "03-XXXX-XXXX"
    };

    confidenceScores = {
      overall: 92,
      accuracy: 95,
      completeness: 88,
      consistency: 92
    };

    // スコア表示
    scoreOverall.textContent = confidenceScores.overall + "%";
    scoreAccuracy.textContent = confidenceScores.accuracy + "%";
    scoreCompleteness.textContent = confidenceScores.completeness + "%";
    scoreConsistency.textContent = confidenceScores.consistency + "%";

    if (confidenceScores.overall < 80) {
      warningFlag.style.display = "block";
    } else {
      warningFlag.style.display = "none";
    }

    // 抽出データをフォームに表示
    renderExtractedData();

    ocrStatus.textContent = "OCR処理完了";
    btnStartOcr.disabled = false;
    isProcessing = false;
    currentStep = Math.min(currentStep + 1, totalSteps);
    updateGuidanceDisplay();
  });

  // ============================================
  // 6. 抽出データ表示・手動修正フォーム
  // ============================================
  function renderExtractedData() {
    extractedDataForm.innerHTML = Object.entries(extractedData).map(([key, value]) => {
      const fieldLabel = key.replace(/_/g, " ").toUpperCase();
      const confidence = Math.floor(Math.random() * 30) + 70; // ダミー信頼度
      const isLowConfidence = confidence < 80;

      return `
        <div style="padding: 8px; background: ${isLowConfidence ? 'rgba(255,107,107,0.1)' : 'rgba(0,0,0,0.2)'}; border-left: 3px solid ${isLowConfidence ? '#ff6b6b' : 'var(--primary)'}; border-radius: 3px;">
          <label style="font-size: 10px; color: var(--text-muted); display: block; margin-bottom: 3px;">
            ${fieldLabel} <span style="color: #ff9999;">(信頼度: ${confidence}%)</span>
          </label>
          <input type="text" value="${value}" data-field="${key}" class="input extracted-field" style="width: 100%; padding: 6px; font-size: 12px; border: 1px solid rgba(255,255,255,0.18); background: rgba(0,0,0,0.3); color: var(--text); border-radius: 3px;">
        </div>
      `;
    }).join("");

    // 抽出項目リスト（左列）
    extractedItemsList.innerHTML = Object.keys(extractedData).map(key => {
      const label = key.replace(/_/g, " ");
      return `<div style="padding: 4px 0; border-bottom: 1px solid rgba(255,255,255,0.08);">✓ ${label}</div>`;
    }).join("");
  }

  // ============================================
  // 7. データ確定・修正保存
  // ============================================
  btnConfirmData.addEventListener("click", async () => {
    // 修正されたデータを収集
    const modifiedData = {};
    container.querySelectorAll(".extracted-field").forEach(input => {
      modifiedData[input.dataset.field] = input.value;
    });

    // API経由で保存（AI_OCR読み込み結果テーブルに記録）
    const ocrResult = {
      source_document_type: "order_form",
      ocr_engine_version: "v2.1",
      raw_ocr_text: JSON.stringify(extractedData),
      extracted_fields: JSON.stringify(modifiedData),
      overall_confidence: confidenceScores.overall,
      processing_status: "success",
      requires_manual_review: confidenceScores.overall < 85
    };

    const saved = await window.aivicApi.save(3, ocrResult); // テーブルインデックス 3 = AI_OCR読み込み結果
    if (saved) {
      alert("データが確定されました。次のステップに進みます。");
      currentStep = totalSteps;
      updateGuidanceDisplay();
      // 次画面へ遷移
      window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面
    }
  });

  btnRetryOcr.addEventListener("click", () => {
    capturedImage = null;
    extractedData = {};
    confidenceScores = {};
    imagePreview.innerHTML = "撮影またはアップロード後に表示";
    extractedDataForm.innerHTML = '<div style="padding: 8px; background: rgba(255,255,255,0.04); border-radius: 3px; text-align: center; color: var(--text-muted); font-size: 11px;">OCR実行後に表示されます</div>';
    scoreOverall.textContent = "—";
    scoreAccuracy.textContent = "—";
    scoreCompleteness.textContent = "—";
    scoreConsistency.textContent = "—";
    warningFlag.style.display = "none";
    ocrProgressBar.style.width = "0%";
    ocrProgressText.textContent = "0%";
    ocrStatus.textContent = "待機中";
    currentStep = Math.max(currentStep - 1, 1);
    updateGuidanceDisplay();
  });

  btnGotoDashboard.addEventListener("click", () => {
    window.showScreen("scr-1781413262699"); // 受注データ検証ダッシュボード
  });

  // ============================================
  // 8. 初期化
  // ============================================
  updateGuidanceDisplay();
}

