function(container, apiUrl, tables) {
  const tbody = container.querySelector("#record-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const detailCloseBtn = container.querySelector("[data-testid='detail-close-button']");
  const detailEditBtn = container.querySelector("[data-testid='detail-edit-button']");
  const searchBtn = container.querySelector("[data-testid='search-button']");
  const exportBtn = container.querySelector("[data-testid='export-button']");

  const scoreMinInput = container.querySelector("[data-testid='score-min']");
  const scoreMaxInput = container.querySelector("[data-testid='score-max']");
  const channelFilter = container.querySelector("[data-testid='channel-filter']");
  const statusFilter = container.querySelector("[data-testid='status-filter']");
  const orderIdSearch = container.querySelector("[data-testid='order-id-search']");
  const sortOrder = container.querySelector("[data-testid='sort-order']");

  let allRecords = [];
  let selectedRecordId = null;

  // 1. 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const scoreClass = r.総合スコア >= 80 ? 'score-high' : r.総合スコア >= 60 ? 'score-mid' : 'score-low';
      const warningIcon = r.警告フラグ ? '⚠' : '';
      return `
        <tr data-id="${r.信頼度スコアID || r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.06); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background=''">
          <td style="padding: 8px 12px; color: var(--text); font-size: 11px; font-weight: 500;">${(r.受注データID || '').substring(0, 8)}</td>
          <td style="padding: 8px 12px; color: #ffd700; font-size: 12px; font-weight: 700;">${r.総合スコア || 0}</td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 11px;">${r.完全性スコア || 0}</td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 11px;">${r.正確性スコア || 0}</td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 11px;">${r.一貫性スコア || 0}</td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-size: 11px;">${r.チャネル || '—'}</td>
          <td style="padding: 8px 12px; font-size: 11px;">
            <span style="padding: 2px 6px; border-radius: 2px; background: ${r.検証ステータス === '合格' ? 'rgba(76,175,80,0.2); color: #4caf50;' : r.検証ステータス === '不合格' ? 'rgba(244,67,54,0.2); color: #f44336;' : r.検証ステータス === '警告' ? 'rgba(255,193,7,0.2); color: #ffc107;' : 'rgba(158,158,158,0.2); color: #9e9e9e;'}">${r.検証ステータス || '—'}</span>
          </td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px; text-align: center;">${warningIcon}</td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ描画
  allRecords = tables[0]?.records || [];
  renderRows(allRecords);

  // 3. 行クリックで詳細パネル表示
  tbody.addEventListener("click", (e) => {
    const row = e.target.closest("tr");
    if (!row) return;
    selectedRecordId = row.dataset.id;
    const record = allRecords.find(r => (r.信頼度スコアID || r.id) === selectedRecordId);
    if (!record) return;

    // 詳細パネルに情報を設定
    container.querySelector("#detail-order-id").textContent = (record.受注データID || '').substring(0, 12);
    container.querySelector("#detail-channel").textContent = record.チャネル || '—';
    container.querySelector("#detail-verified-at").textContent = record.スコア計算日時 ? new Date(record.スコア計算日時).toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—';
    container.querySelector("#detail-warning-level").textContent = record.警告レベル || '—';
    container.querySelector("#detail-total-score").textContent = record.総合スコア || '—';
    container.querySelector("#detail-completeness-score").textContent = record.完全性スコア || '—';
    container.querySelector("#detail-accuracy-score").textContent = record.正確性スコア || '—';
    container.querySelector("#detail-consistency-score").textContent = record.一貫性スコア || '—';
    container.querySelector("#detail-validation-results").innerHTML = record.検証結果 ? `<div style="color: var(--text);">${record.検証結果}</div>` : '<div style="color: var(--text-muted);">検証結果なし</div>';
    container.querySelector("#detail-ocr-confidence").textContent = record.OCR信頼度 ? `${record.OCR信頼度}%` : '—';
    container.querySelector("#detail-ocr-status").textContent = record.OCRステータス || '—';
    container.querySelector("#detail-duplicate-results").innerHTML = record.重複検出結果 ? `<div style="color: var(--text);">${record.重複検出結果}</div>` : '<div style="color: var(--text-muted);">検出なし</div>';
    container.querySelector("#detail-channel-conflict-results").innerHTML = record.チャネル間矛盾結果 ? `<div style="color: var(--text);">${record.チャネル間矛盾結果}</div>` : '<div style="color: var(--text-muted);">検出なし</div>';
    container.querySelector("#detail-missing-input-results").innerHTML = record.入力漏れ結果 ? `<div style="color: var(--text);">${record.入力漏れ結果}</div>` : '<div style="color: var(--text-muted);">検出なし</div>';

    detailPanel.style.display = "block";
  });

  // 詳細パネル閉じる
  detailCloseBtn.addEventListener("click", () => {
    detailPanel.style.display = "none";
    selectedRecordId = null;
  });

  // 詳細確認ボタン → 詳細確認・修正画面へ遷移
  detailEditBtn.addEventListener("click", () => {
    if (selectedRecordId) {
      window.showScreen("scr-1781413282852");
    }
  });

  // 4. 検索ボタン
  searchBtn.addEventListener("click", () => {
    const scoreMin = parseFloat(scoreMinInput.value) || 0;
    const scoreMax = parseFloat(scoreMaxInput.value) || 100;
    const channel = channelFilter.value;
    const status = statusFilter.value;
    const orderId = orderIdSearch.value.toLowerCase();
    const sort = sortOrder.value;

    let filtered = allRecords.filter(r => {
      const score = r.総合スコア || 0;
      const matchScore = score >= scoreMin && score <= scoreMax;
      const matchChannel = !channel || r.チャネル === channel;
      const matchStatus = !status || r.検証ステータス === status;
      const matchOrderId = !orderId || (r.受注データID || '').toLowerCase().includes(orderId);
      return matchScore && matchChannel && matchStatus && matchOrderId;
    });

    // ソート
    if (sort === "asc") {
      filtered.sort((a, b) => (a.総合スコア || 0) - (b.総合スコア || 0));
    } else {
      filtered.sort((a, b) => (b.総合スコア || 0) - (a.総合スコア || 0));
    }

    renderRows(filtered);
  });

  // 5. CSVエクスポート
  exportBtn.addEventListener("click", () => {
    const headers = ["受注ID", "総合スコア", "完全性", "正確性", "一貫性", "チャネル", "検証ステータス", "警告"];
    const rows = allRecords.map(r => [
      (r.受注データID || '').substring(0, 8),
      r.総合スコア || 0,
      r.完全性スコア || 0,
      r.正確性スコア || 0,
      r.一貫性スコア || 0,
      r.チャネル || '',
      r.検証ステータス || '',
      r.警告フラグ ? '⚠' : ''
    ]);

    const csv = [
      '\uFEFF' + headers.join(','),
      ...rows.map(row => row.map(cell => typeof cell === 'string' && cell.includes(',') ? `"${cell}"` : cell).join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `信頼度スコア_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const correctionHistoryTableIndex = tables.findIndex(t => t.tableName === '受注データ修正履歴') ?? 0;
  const validationResultTableIndex = tables.findIndex(t => t.tableName === '受注データ検証結果') ?? 1;
  const trustScoreTableIndex = tables.findIndex(t => t.tableName === '信頼度スコア') ?? 2;
  const approvalFlowTableIndex = tables.findIndex(t => t.tableName === '連携承認フロー') ?? 3;

  // 修正履歴データの再描画
  function renderCorrectionHistory(rows) {
    const timeline = container.querySelector("#history-timeline");
    if (!timeline) return;

    // 直近5件を表示
    const recentRows = (rows || []).slice(0, 5);
    timeline.innerHTML = recentRows.map((row, idx) => {
      const color = idx % 2 === 0 ? '#4ade80' : '#ff9500';
      return `
        <div style="margin-bottom: 16px; position: relative;">
          <div style="position: absolute; left: -20px; top: 2px; width: 12px; height: 12px; background: ${color}; border-radius: 50%; border: 2px solid var(--bg-main);"></div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">${row.修正日時 || '—'}</div>
          <div style="font-size: 12px; color: var(--text); font-weight: 500; margin-bottom: 4px;">${row.修正項目名 || '修正'}</div>
          <div style="font-size: 11px; color: var(--text-muted); background: var(--bg-card); padding: 6px 8px; border-radius: 3px;">
            修正者: ${row.修正ユーザーID || '—'} | 理由: ${row.修正理由 || '—'}
          </div>
        </div>
      `;
    }).join("");
  }

  // 差分表示の更新
  function renderDiffView(rows) {
    const diffContainer = container.querySelector("#diff-container");
    if (!rows || rows.length === 0) return;

    diffContainer.innerHTML = rows.map(row => `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding: 10px; background: var(--bg-card); border-radius: 4px; border-left: 3px solid #ff6a00;">
        <div>
          <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 4px;">${row.修正項目名}（修正前）</div>
          <div style="font-size: 13px; color: #ff6a00; font-weight: 500; text-decoration: line-through;">${row.修正前値 || '—'}</div>
        </div>
        <div>
          <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 4px;">${row.修正項目名}（修正後）</div>
          <div style="font-size: 13px; color: #4ade80; font-weight: 500;">${row.修正後値 || '—'}</div>
        </div>
      </div>
    `).join("");
  }

  // 初期データの読み込みと表示
  async function initializeScreen() {
    try {
      const historyRows = await window.aivicApi.list(correctionHistoryTableIndex);
      renderCorrectionHistory(historyRows);
      renderDiffView(historyRows);
    } catch (err) {
      console.error("Failed to load correction history:", err);
    }
  }

  // 保存ボタンのイベントリスナー
  const saveBtn = container.querySelector("[data-testid='save-button']");
  if (saveBtn) {
    saveBtn.addEventListener("click", async () => {
      const reason = container.querySelector("[data-testid='correction-reason-select']").value;
      const notes = container.querySelector("[data-testid='correction-notes']").value;

      if (!reason) {
        alert("修正理由を選択してください");
        return;
      }

      try {
        const newRecord = {
          受注データID: "ORD-2024-001234",
          修正項目名: "複数項目",
          修正前値: "100,000",
          修正後値: "105,000",
          修正理由: reason,
          修正備考: notes,
          修正ユーザーID: "user-001",
          修正日時: new Date().toISOString().slice(0, 16).replace('T', ' ')
        };

        const saved = await window.aivicApi.save(correctionHistoryTableIndex, newRecord);
        if (saved) {
          alert("修正内容を保存しました");
          container.querySelector("[data-testid='correction-reason-select']").value = "";
          container.querySelector("[data-testid='correction-notes']").value = "";

          // 履歴を再読み込み
          const updated = await window.aivicApi.list(correctionHistoryTableIndex);
          renderCorrectionHistory(updated);
          renderDiffView(updated);
        }
      } catch (err) {
        console.error("Save failed:", err);
      }
    });
  }

  // キャンセルボタンのイベントリスナー
  const cancelBtn = container.querySelector("[data-testid='cancel-button']");
  if (cancelBtn) {
    cancelBtn.addEventListener("click", () => {
      if (confirm("修正内容を破棄しますか？")) {
        container.querySelector("[data-testid='correction-reason-select']").value = "";
        container.querySelector("[data-testid='correction-notes']").value = "";
      }
    });
  }

  // 修正履歴をすべて表示ボタン
  const viewFullHistoryBtn = container.querySelector("[data-testid='view-full-history-button']");
  if (viewFullHistoryBtn) {
    viewFullHistoryBtn.addEventListener("click", () => {
      // 修正対象優先度リスト画面へ遷移
      window.showScreen("scr-1781413354977");
    });
  }

  // 初期化実行
  initializeScreen();
}

