          <thead>
            <tr style="border-bottom: 1px solid rgba(255,255,255,0.12); background: rgba(255,255,255,0.04);">
              <th style="padding: 6px; text-align: left; color: var(--text); font-weight: 600;">項目</th>
              <th style="padding: 6px; text-align: left; color: var(--text); font-weight: 600;">主受注</th>
              <th style="padding: 6px; text-align: left; color: var(--text); font-weight: 600;">副受注</th>
              <th style="padding: 6px; text-align: center; color: var(--text); font-weight: 600;">矛盾</th>
            </tr>
          </thead>
          <tbody>
            <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
              <td style="padding: 6px; color: var(--text-muted);">受注ID</td>
              <td style="padding: 6px; color: var(--text);">${duplicate.主受注ID?.substring(0, 12) || 'N/A'}</td>
              <td style="padding: 6px; color: var(--text);">${duplicate.副受注ID?.substring(0, 12) || 'N/A'}</td>
              <td style="padding: 6px; text-align: center; color: #90caf9;">✓</td>
            </tr>
            <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
              <td style="padding: 6px; color: var(--text-muted);">マッチング理由</td>
              <td colspan="3" style="padding: 6px; color: var(--text);">${duplicate.マッチング理由 || '不明'}</td>
            </tr>
            <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
              <td style="padding: 6px; color: var(--text-muted);">検出ルール</td>
              <td colspan="3" style="padding: 6px; color: var(--text);">${duplicate.検出ルールID || 'ルール001'}</td>
            </tr>
            <tr>
              <td style="padding: 6px; color: var(--text-muted);">信頼度スコア</td>
              <td colspan="3" style="padding: 6px; color: var(--text);">
                <div style="display: flex; align-items: center; gap: 8px;">
                  <div style="flex: 1; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden;">
                    <div style="height: 100%; width: ${duplicate.マッチング信頼度 || 0}%; background: ${duplicate.マッチング信頼度 >= 90 ? '#ff6a00' : duplicate.マッチング信頼度 >= 70 ? '#ffc107' : '#64b5f6'}; transition: width 0.3s;"></div>
                  </div>
                  <span>${duplicate.マッチング信頼度 || 0}%</span>
                </div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <div style="margin-bottom: 16px;">
        <div style="font-size: 12px; font-weight: 600; color: var(--text); margin-bottom: 8px;">
          対応方針
        </div>
        <div style="padding: 8px; background: rgba(255,255,255,0.04); border-radius: 3px; border-left: 3px solid ${
          duplicate.対応方針 === '統合' ? '#ff6a00' : 
          duplicate.対応方針 === '分離' ? '#64b5f6' : 
          duplicate.対応方針 === '保留' ? '#ffc107' : '#9fb0d1'
        };">
          <div style="font-size: 12px; color: var(--text);">
            ${duplicate.対応方針 || '未決定'}
          </div>
          ${duplicate.備考 ? `<div style="font-size: 11px; color: var(--text-muted); margin-top: 4px;">${duplicate.備考}</div>` : ''}
        </div>
      </div>
    `;
  }

  // ============ 2. 初期データ読み込み ============
  async function loadInitialData() {
    const duplicates = tables[DUPLICATE_RESULTS_IDX]?.records || [];
    allDuplicates = duplicates;
    renderDuplicateGroups(allDuplicates);
    renderDetailComparison(null);
  }

  loadInitialData();

  // ============ 3. 検索ボタン ============
  container.querySelector('[data-testid="search-button"]').addEventListener("click", async () => {
    const keyword = container.querySelector('[data-testid="search-keyword"]').value.toLowerCase();
    const status = container.querySelector('[data-testid="status-filter"]').value;
    const confidence = container.querySelector('[data-testid="confidence-filter"]').value;

    let filtered = allDuplicates;

    if (keyword) {
      filtered = filtered.filter(d => 
        (d.主受注ID || '').toLowerCase().includes(keyword) ||
        (d.副受注ID || '').toLowerCase().includes(keyword) ||
        (d.マッチング理由 || '').toLowerCase().includes(keyword)
      );
    }

    if (status) {
      filtered = filtered.filter(d => d.検出ステータス === status);
    }

    if (confidence) {
      const confNum = parseInt(confidence);
      if (confNum === 0) {
        filtered = filtered.filter(d => (d.マッチング信頼度 || 0) < 50);
      } else if (confNum === 50) {
        filtered = filtered.filter(d => (d.マッチング信頼度 || 0) >= 50 && (d.マッチング信頼度 || 0) < 70);
      } else if (confNum === 70) {
        filtered = filtered.filter(d => (d.マッチング信頼度 || 0) >= 70 && (d.マッチング信頼度 || 0) < 90);
      } else if (confNum === 90) {
        filtered = filtered.filter(d => (d.マッチング信頼度 || 0) >= 90);
      }
    }

    renderDuplicateGroups(filtered);
    selectedDuplicate = null;
    renderDetailComparison(null);
  });

  // ============ 4. リセットボタン ============
  container.querySelector('[data-testid="reset-button"]').addEventListener("click", () => {
    container.querySelector('[data-testid="search-keyword"]').value = '';
    container.querySelector('[data-testid="status-filter"]').value = '';
    container.querySelector('[data-testid="confidence-filter"]').value = '';
    renderDuplicateGroups(allDuplicates);
    selectedDuplicate = null;
    renderDetailComparison(null);
  });

  // ============ 5. グループ選択（イベントデリゲーション） ============
  container.addEventListener("click", (e) => {
    const groupItem = e.target.closest(".duplicate-group-item");
    if (groupItem) {
      const id = groupItem.dataset.id;
      selectedDuplicate = allDuplicates.find(d => d.id === id);

      // ハイライト更新
      container.querySelectorAll(".duplicate-group-item").forEach(item => {
        item.style.borderColor = item.dataset.id === id ? 'var(--primary)' : 'rgba(255,255,255,0.12)';
        item.style.background = item.dataset.id === id ? 'rgba(255,107,0,0.08)' : 'var(--bg-main)';
      });

      renderDetailComparison(selectedDuplicate);
    }
  });

  // ============ 6. 修正保存ボタン ============
  container.querySelector('[data-testid="save-correction-button"]').addEventListener("click", async () => {
    if (!selectedDuplicate) {
      alert("修正対象の重複グループを選択してください");
      return;
    }

    const action = container.querySelector('[data-testid="correction-action"]').value;
    const reason = container.querySelector('[data-testid="correction-reason"]').value;
    const notes = container.querySelector('[data-testid="correction-notes"]').value;

    if (!action || !reason) {
      alert("修正内容と修正理由を選択してください");
      return;
    }

    // 修正結果を保存
    const correctionData = {
      重複受注検出結果ID: selectedDuplicate.id,
      対応方針: action,
      修正理由: reason,
      備考: notes,
      確認者ID: "current-user-id",
      確認日時: new Date().toISOString(),
      検出ステータス: action === '統合' ? '統合済み' : action === '分離' ? '誤検出' : '確認済み'
    };

    const saved = await window.aivicApi.update(DUPLICATE_RESULTS_IDX, selectedDuplicate.id, correctionData);

    if (saved) {
      alert("修正を保存しました");
      // 修正履歴に記録
      await window.aivicApi.save(CORRECTION_HISTORY_IDX, {
        受注データID: selectedDuplicate.主受注ID,
        修正項目名: '重複受注対応',
        修正前値: selectedDuplicate.検出ステータス,
        修正後値: correctionData.検出ステータス,
        修正理由: reason,
        修正備考: notes,
        修正ユーザーID: "current-user-id",
        修正日時: new Date().toISOString()
      });

      // UI リセット
      container.querySelector('[data-testid="correction-action"]').value = '';
      container.querySelector('[data-testid="correction-reason"]').value = '';
      container.querySelector('[data-testid="correction-notes"]').value = '';

      // データ再読み込み
      const updated = await window.aivicApi.list(DUPLICATE_RESULTS_IDX);
      allDuplicates = updated || [];
      renderDuplicateGroups(allDuplicates);
      selectedDuplicate = null;
      renderDetailComparison(null);
    }
  });

  // ============ 7. キャンセルボタン ============
  container.querySelector('[data-testid="cancel-correction-button"]').addEventListener("click", () => {
    container.querySelector('[data-testid="correction-action"]').value = '';
    container.querySelector('[data-testid="correction-reason"]').value = '';
    container.querySelector('[data-testid="correction-notes"]').value = '';
  });

  // ============ 8. ダッシュボードへリンク ============
  container.querySelector('[data-testid="view-dashboard-link"]').addEventListener("click", (e) => {
    e.preventDefault();
    window.showScreen("scr-1781413262699");
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0 = 受注データ検証結果
  const tableIndex = 0;
  const tbody = container.querySelector("#validation-tbody");
  const recordCountEl = container.querySelector("[data-testid='record-count']");
  const errorDetailEl = container.querySelector("#error-detail");
  const duplicateWarningEl = container.querySelector("#duplicate-warning");
  const channelConflictEl = container.querySelector("#channel-conflict");
  const missingInputEl = container.querySelector("#missing-input");
  const correctionSuggestionsEl = container.querySelector("#correction-suggestions");
  const scoreDisplayEl = container.querySelector("[data-testid='score-display']");
  const scoreCompletenessEl = container.querySelector("[data-testid='score-completeness']");
  const scoreAccuracyEl = container.querySelector("[data-testid='score-accuracy']");
  const scoreConsistencyEl = container.querySelector("[data-testid='score-consistency']");
  const scoreWarningEl = container.querySelector("[data-testid='score-warning']");

  let currentSelectedId = null;
  let allValidationResults = [];

  // 1. 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const statusColor = r.検証ステータス === "合格" ? "#4caf50" : 
                          r.検証ステータス === "不合格" ? "#f44336" : 
                          r.検証ステータス === "警告" ? "#ff9800" : "#9c27b0";
      const severityColor = r.重要度 === "致命的" ? "#f44336" : 
                            r.重要度 === "高" ? "#ff9800" : 
                            r.重要度 === "中" ? "#ffc107" : "#4caf50";
      return `
        <tr data-id="${r.検証結果ID || r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.04); cursor: pointer; transition: background 0.15s;">
          <td style="padding: 8px; color: var(--text-muted); word-break: break-all;">${(r.検証結果ID || r.id || "").substring(0, 8)}</td>
          <td style="padding: 8px; color: var(--text);">${r.受注データID || "—"}</td>
          <td style="padding: 8px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${statusColor}20; color: ${statusColor}; font-size: 10px; font-weight: 600;">
              ${r.検証ステータス || "—"}
            </span>
          </td>
          <td style="padding: 8px; color: var(--text);">${r.検証項目 || "—"}</td>
          <td style="padding: 8px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${severityColor}20; color: ${severityColor}; font-size: 10px; font-weight: 600;">
              ${r.重要度 || "—"}
            </span>
          </td>
          <td style="padding: 8px; color: var(--text-muted);">${r.エラーコード || "—"}</td>
          <td style="padding: 8px; color: var(--text-muted); font-size: 11px;">${r.検証実行日時 ? new Date(r.検証実行日時).toLocaleString("ja-JP") : "—"}</td>
          <td style="padding: 8px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${r.検証結果ID || r.id}" style="padding: 4px 8px; font-size: 10px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
    recordCountEl.textContent = rows.length;
  }

  // 2. 初期データ描画
  if (tables[0] && tables[0].records) {
    allValidationResults = tables[0].records;
    renderRows(allValidationResults);
  }

  // 3. 行クリックで詳細表示
  tbody.addEventListener("click", (e) => {
    const row = e.target.closest("tr");
    if (row) {
      currentSelectedId = row.dataset.id;
      const record = allValidationResults.find(r => (r.検証結果ID || r.id) === currentSelectedId);
      if (record) {
        // エラー詳細
        errorDetailEl.innerHTML = `
          <div style="margin-bottom: 6px;">
            <div style="color: var(--text-muted); font-size: 10px;">エラーメッセージ</div>
            <div style="color: var(--text); margin-top: 2px;">${record.エラーメッセージ || "なし"}</div>
          </div>
          <div style="margin-bottom: 6px;">
            <div style="color: var(--text-muted); font-size: 10px;">検証値</div>
            <div style="color: var(--text); margin-top: 2px; word-break: break-all;">${record.検証値 || "—"}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); font-size: 10px;">期待値</div>
            <div style="color: var(--text); margin-top: 2px; word-break: break-all;">${record.期待値 || "—"}</div>
          </div>
        `;
        // 信頼度スコア（ダミー値）
        scoreDisplayEl.textContent = Math.floor(Math.random() * 40 + 60);
        scoreCompletenessEl.textContent = Math.floor(Math.random() * 30 + 70);
        scoreAccuracyEl.textContent = Math.floor(Math.random() * 30 + 70);
        scoreConsistencyEl.textContent = Math.floor(Math.random() * 30 + 70);
        scoreWarningEl.textContent = record.重要度 === "致命的" ? "高" : record.重要度 === "高" ? "中" : "低";
        // 重複受注警告（ダミー）
        duplicateWarningEl.innerHTML = `<div style="color: var(--text);">検出なし</div>`;
        // チャネル間矛盾（ダミー）
        channelConflictEl.innerHTML = `<div style="color: var(--text);">検出なし</div>`;
        // 入力漏れ（ダミー）
        missingInputEl.innerHTML = `<div style="color: var(--text);">検出なし</div>`;
        // 修正提案
        correctionSuggestionsEl.innerHTML = `
          <div style="background: rgba(255,255,255,0.04); padding: 8px; border-radius: 3px; border-left: 2px solid var(--primary);">
            <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 4px;">推奨修正</div>
            <div style="color: var(--text); font-size: 11px; margin-bottom: 6px;">
              ${record.検証項目} を確認し、期待値に合わせて修正してください
            </div>
            <button class="action-btn" style="padding: 4px 8px; font-size: 10px; width: 100%;">修正画面へ</button>
          </div>
        `;
      }
    }
  });

  // 4. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", () => {
    const statusFilter = container.querySelector("[data-testid='status-filter']").value;
    const channelFilter = container.querySelector("[data-testid='channel-filter']").value;
    const dateFrom = container.querySelector("[data-testid='date-from']").value;
    const dateTo = container.querySelector("[data-testid='date-to']").value;

    let filtered = allValidationResults;
    if (statusFilter) {
      filtered = filtered.filter(r => r.検証ステータス === statusFilter);
    }
    if (channelFilter) {
      filtered = filtered.filter(r => r.チャネル === channelFilter);
    }
    if (dateFrom) {
      const from = new Date(dateFrom);
      filtered = filtered.filter(r => new Date(r.検証実行日時) >= from);
    }
    if (dateTo) {
      const to = new Date(dateTo);
      to.setHours(23, 59, 59);
      filtered = filtered.filter(r => new Date(r.検証実行日時) <= to);
    }
    renderRows(filtered);
  });

  // 5. 自動検証実行ボタン
  container.querySelector("[data-testid='validate-button']").addEventListener("click", async () => {
    alert("自動検証を実行します。\n（本番環境では検証エンジンが起動します）");
    // 実際の実装では window.aivicApi.save() で検証ジョブを登録
  });

  // 6. 詳細確認ボタン
  container.querySelector("[data-testid='detail-button']").addEventListener("click", () => {
    if (currentSelectedId) {
      window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面
    } else {
      alert("行を選択してください");
    }
  });

  // 7. CSVエクスポート
  container.querySelector("[data-testid='export-button']").addEventListener("click", () => {
    if (allValidationResults.length === 0) {
      alert("エクスポート対象がありません");
      return;
    }
    const headers = ["検証結果ID", "受注データID", "検証ステータス", "検証項目", "重要度", "エラーコード", "エラーメッセージ", "検証実行日時"];
    const rows = allValidationResults.map(r => [
      r.検証結果ID || r.id || "",
      r.受注データID || "",
      r.検証ステータス || "",
      r.検証項目 || "",
      r.重要度 || "",
      r.エラーコード || "",
      (r.エラーメッセージ || "").replace(/"/g, '""'),
      r.検証実行日時 ? new Date(r.検証実行日時).toLocaleString("ja-JP") : ""
    ]);
    const csv = "\uFEFF" + [headers, ...rows].map(r => r.map(v => `"${v}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `validation_results_${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });

  // 8. ダッシュボードボタン
  container.querySelector("[data-testid='dashboard-button']").addEventListener("click", () => {
    window.showScreen("scr-1781413262699"); // 受注データ検証ダッシュボード
  });

  // 9. 詳細ボタン（行レベル）
  tbody.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      currentSelectedId = detailBtn.dataset.id;
      window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（仮定）
  const VALIDATION_RESULTS_IDX = 0;
  const CORRECTION_HISTORY_IDX = 1;
  const TRUST_SCORE_IDX = 2;
  const DUPLICATE_DETECTION_IDX = 3;
  const CHANNEL_CONFLICT_IDX = 4;

  let selectedOrderId = null;
  let allValidationResults = [];
  let allCorrectionHistory = [];
  let allTrustScores = [];
  let allDuplicateDetections = [];
  let allChannelConflicts = [];

  // 1. 初期データ読み込み
  async function loadAllData() {
    try {
      allValidationResults = await window.aivicApi.list(VALIDATION_RESULTS_IDX) || tables[VALIDATION_RESULTS_IDX]?.records || [];
      allCorrectionHistory = await window.aivicApi.list(CORRECTION_HISTORY_IDX) || tables[CORRECTION_HISTORY_IDX]?.records || [];
      allTrustScores = await window.aivicApi.list(TRUST_SCORE_IDX) || tables[TRUST_SCORE_IDX]?.records || [];
      allDuplicateDetections = await window.aivicApi.list(DUPLICATE_DETECTION_IDX) || tables[DUPLICATE_DETECTION_IDX]?.records || [];
      allChannelConflicts = await window.aivicApi.list(CHANNEL_CONFLICT_IDX) || tables[CHANNEL_CONFLICT_IDX]?.records || [];
      renderOrderList(allCorrectionHistory);
    } catch (e) {
      console.error('Data load error:', e);
    }
  }

  // 2. 修正対象受注一覧の再描画
  function renderOrderList(rows) {
    const tbody = container.querySelector('#order-list-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: rgba(255,255,255,0.04); border-bottom: 1px solid rgba(255,255,255,0.08);"><td style="padding: 6px 8px; color: var(--text-muted);">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id || row.修正履歴ID}" style="background: rgba(255,255,255,0.04); border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s;" 
        onmouseover="this.style.background='rgba(255,255,255,0.08)'" 
        onmouseout="this.style.background='rgba(255,255,255,0.04)'">
        <td style="padding: 6px 8px; font-size: 11px; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">
          <strong>${(row.受注データID || row.orderId || '—').substring(0, 8)}</strong><br/>
          <span style="color: var(--text-muted); font-size: 10px;">${row.修正項目名 || row.fieldName || '—'}</span>
        </td>
      </tr>
    `).join('');
  }

  // 3. 受注選択時の詳細表示
  function showOrderDetail(orderId) {
    selectedOrderId = orderId;

    // 修正履歴を取得
    const corrHistory = allCorrectionHistory.find(r => r.id === orderId || r.修正履歴ID === orderId);
    if (!corrHistory) {
      container.querySelector('#diff-before').textContent = '（データなし）';
      container.querySelector('#diff-after').textContent = '（データなし）';
      return;
    }

    // 修正前後の差分表示
    container.querySelector('#diff-before').textContent = corrHistory.修正前値 || corrHistory.beforeValue || '—';
    container.querySelector('#diff-after').textContent = corrHistory.修正後値 || corrHistory.afterValue || '—';

    // メタデータ表示
    container.querySelector('#meta-modifier').textContent = corrHistory.修正ユーザーID || corrHistory.modifierId || '—';
    container.querySelector('#meta-modified-at').textContent = corrHistory.修正日時 || corrHistory.modifiedAt || '—';
    container.querySelector('#meta-reason').textContent = corrHistory.修正理由 || corrHistory.reason || '—';
    container.querySelector('#meta-notes').textContent = corrHistory.修正備考 || corrHistory.notes || '—';
    container.querySelector('#modifier-name').textContent = corrHistory.修正ユーザーID || '—';
    container.querySelector('#modified-at').textContent = (corrHistory.修正日時 || '—').substring(0, 16);

    // 検証結果を取得
    const valResult = allValidationResults.find(r => r.受注データID === corrHistory.受注データID || r.orderId === corrHistory.受注データID);
    if (valResult) {
      renderValidationResults(valResult);
    }

    // 信頼度スコアを取得
    const trustScore = allTrustScores.find(r => r.受注データID === corrHistory.受注データID || r.orderId === corrHistory.受注データID);
    if (trustScore) {
      container.querySelector('#score-total').textContent = trustScore.総合スコア || trustScore.totalScore || '—';
      container.querySelector('#score-warning').textContent = trustScore.警告フラグ ? '⚠' : '✓';
      container.querySelector('#score-completeness').textContent = trustScore.完全性スコア || trustScore.completenessScore || '—';
      container.querySelector('#score-accuracy').textContent = trustScore.正確性スコア || trustScore.accuracyScore || '—';
      container.querySelector('#score-consistency').textContent = trustScore.一貫性スコア || trustScore.consistencyScore || '—';
    }

    // 重複受注検出結果
    const dupResult = allDuplicateDetections.find(r => 
      r.主受注ID === corrHistory.受注データID || r.副受注ID === corrHistory.受注データID ||
      r.primaryOrderId === corrHistory.受注データID || r.secondaryOrderId === corrHistory.受注データID
    );
    container.querySelector('#duplicate-result').textContent = dupResult 
      ? `${dupResult.検出ステータス || dupResult.status || '未確認'} (信頼度: ${dupResult.マッチング信頼度 || dupResult.confidence || '—'}%)`
      : '検出なし';

    // チャネル間矛盾検出結果
    const conflictResult = allChannelConflicts.find(r => 
      r.受注ID_1 === corrHistory.受注データID || r.受注ID_2 === corrHistory.受注データID ||
      r.orderId1 === corrHistory.受注データID || r.orderId2 === corrHistory.受注データID
    );
    container.querySelector('#channel-conflict-result').textContent = conflictResult 
      ? `${conflictResult.矛盾タイプ || conflictResult.conflictType || '—'} (${conflictResult.重要度 || conflictResult.severity || '—'})`
      : '矛盾なし';
  }

  // 4. 検証結果の表示
  function renderValidationResults(valResult) {
    const container_val = container.querySelector('#validation-results');
    const errors = [];
    if (valResult.検証ステータス === '不合格' || valResult.status === 'FAILED') {
      errors.push({
        code: valResult.エラーコード || valResult.errorCode || 'ERR_UNKNOWN',
        message: valResult.エラーメッセージ || valResult.errorMessage || '不明なエラー',
        severity: valResult.重要度 || valResult.severity || '中'
      });
    }
    if (valResult.検証ステータス === '警告' || valResult.status === 'WARNING') {
      errors.push({
        code: 'WARN_001',
        message: valResult.エラーメッセージ || '警告が検出されました',
        severity: '低'
      });
    }
    if (errors.length === 0) {
      container_val.innerHTML = '<div style="color: #4ade80; padding: 8px; text-align: center; font-weight: 600;">✓ 検証合格</div>';
    } else {
      container_val.innerHTML = errors.map(e => `
        <div style="background: rgba(${e.severity === '高' ? '239,68,68' : e.severity === '中' ? '251,191,36' : '74,222,128'},0.15); border-left: 3px solid ${e.severity === '高' ? '#ef4444' : e.severity === '中' ? '#fbbf24' : '#4ade80'}; border-radius: 3px; padding: 6px; margin-bottom: 4px;">
          <div style="font-size: 10px; font-weight: 600; color: var(--text);">${e.code}</div>
          <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${e.message}</div>
        </div>
      `).join('');
    }
  }

  // 5. 検索ボタン
  container.querySelector('#btn-search-order').addEventListener('click', () => {
    const keyword = container.querySelector('#search-order-id').value.toLowerCase();
    const filtered = allCorrectionHistory.filter(r => {
      const orderId = (r.受注データID || r.orderId || '').toLowerCase();
      const itemName = (r.修正項目名 || r.fieldName || '').toLowerCase();
      return orderId.includes(keyword) || itemName.includes(keyword);
    });
    renderOrderList(filtered);
  });

  // 6. 受注一覧の行クリック
  container.addEventListener('click', (e) => {
    const row = e.target.closest('tr[data-id]');
    if (row) {
      const orderId = row.dataset.id;
      showOrderDetail(orderId);
    }
  });

  // 7. 再検証実行ボタン
  container.querySelector('#btn-revalidate').addEventListener('click', async () => {
    if (!selectedOrderId) {
      alert('受注を選択してください');
      return;
    }
    alert('再検証を実行しました（シミュレーション）');
    // 実際の再検証ロジックはここに実装
  });

  // 8. 承認ボタン
  container.querySelector('#btn-approve').addEventListener('click', async () => {
    if (!selectedOrderId) {
      alert('受注を選択してください');
      return;
    }
    if (confirm('この受注データを承認しますか？')) {
      alert('承認しました（シミュレーション）');
      // 実際の承認ロジック
    }
  });

  // 9. 却下ボタン
  container.querySelector('#btn-reject').addEventListener('click', async () => {
    if (!selectedOrderId) {
      alert('受注を選択してください');
      return;
    }
    if (confirm('この受注データを却下しますか？')) {
      alert('却下しました（シミュレーション）');
      // 実際の却下ロジック
    }
  });

  // 10. 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-1781413262699'); // 受注データ検証ダッシュボード
  });

  // 初期化
  loadAllData();
}

function(container, apiUrl, tables) {
  // ============================================
  // 1. Data & State Management
  // ============================================
  let allOrders = [];
  let selectedOrderId = null;
  let selectedOrderData = null;

  // ============================================
  // 2. Render Functions
  // ============================================
  function renderOrderList(orders) {
    const tbody = container.querySelector("#order-tbody");
    tbody.innerHTML = orders.map(order => {
      const statusColor = {
        "待機中": "#ff9800",
        "確認中": "#2196f3",
        "承認済": "#4caf50",
        "却下": "#f44336"
      }[order.current_status] || "#9fb0d1";

      return `
        <tr data-id="${order.id}" class="order-row" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08); transition: background 0.15s;">
          <td style="padding: 8px; color: var(--text);">${order.order_id || "-"}</td>
          <td style="padding: 8px; color: var(--text);">${order.customer_name || "-"}</td>
          <td style="padding: 8px; text-align: right; color: var(--text);">¥${(order.order_amount || 0).toLocaleString()}</td>
          <td style="padding: 8px; color: var(--text);">${order.channel_name || "-"}</td>
          <td style="padding: 8px; text-align: center;">
            <span style="display: inline-block; padding: 2px 6px; background: ${statusColor}; color: #fff; border-radius: 2px; font-size: 11px; font-weight: 600;">${order.current_status || "-"}</span>
          </td>
          <td style="padding: 8px; text-align: center; color: var(--primary); font-weight: 600;">${order.total_score || 0}%</td>
        </tr>
      `;
    }).join("");

    // Add hover effect
    container.querySelectorAll(".order-row").forEach(row => {
      row.addEventListener("mouseenter", () => row.style.background = "rgba(255,255,255,0.05)");
      row.addEventListener("mouseleave", () => row.style.background = "");
      row.addEventListener("click", () => selectOrder(row.dataset.id));
    });
  }

  function selectOrder(orderId) {
    selectedOrderId = orderId;
    selectedOrderData = allOrders.find(o => o.id === orderId);

    // Update row highlight
    container.querySelectorAll(".order-row").forEach(row => {
      row.style.background = row.dataset.id === orderId ? "rgba(255,165,0,0.15)" : "";
    });

    // Render detail panel
    renderDetailPanel();
  }

  function renderDetailPanel() {
    const detailEmpty = container.querySelector("#detail-empty");
    const detailContent = container.querySelector("#detail-content");

    if (!selectedOrderData) {
      detailEmpty.style.display = "block";
      detailContent.style.display = "none";
      return;
    }

    detailEmpty.style.display = "none";
    detailContent.style.display = "flex";

    // Render Issues
    const issuesList = container.querySelector("#issues-list");
    const issues = selectedOrderData.detected_issues ? JSON.parse(selectedOrderData.detected_issues) : [];
    issuesList.innerHTML = issues.length > 0
      ? issues.map(issue => `
          <div style="padding: 6px 8px; background: rgba(244,67,54,0.15); border-left: 2px solid #f44336; border-radius: 2px; color: var(--text);">
            <div style="font-weight: 500;">${issue.error_code || "エラー"}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${issue.error_message || ""}</div>
          </div>
        `).join("")
      : `<div style="color: var(--text-muted); font-size: 12px;">問題なし</div>`;

    // Render Missing Fields
    const missingList = container.querySelector("#missing-list");
    const missing = selectedOrderData.missing_fields ? JSON.parse(selectedOrderData.missing_fields) : [];
    missingList.innerHTML = missing.length > 0
      ? missing.map(field => `
          <div style="padding: 6px 8px; background: rgba(255,193,7,0.15); border-left: 2px solid #ffc107; border-radius: 2px; color: var(--text);">
            <div style="font-weight: 500;">${field.field_name || "項目"}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">区分: ${field.field_category || ""}</div>
          </div>
        `).join("")
      : `<div style="color: var(--text-muted); font-size: 12px;">入力漏れなし</div>`;

    // Render Channel Discrepancies
    const discrepancyList = container.querySelector("#discrepancy-list");
    const discrepancies = selectedOrderData.channel_discrepancies ? JSON.parse(selectedOrderData.channel_discrepancies) : [];
    discrepancyList.innerHTML = discrepancies.length > 0
      ? discrepancies.map(disc => `
          <div style="padding: 6px 8px; background: rgba(33,150,243,0.15); border-left: 2px solid #2196f3; border-radius: 2px; color: var(--text);">
            <div style="font-weight: 500;">${disc.discrepancy_type || "矛盾"}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${disc.discrepancy_content || ""}</div>
          </div>
        `).join("")
      : `<div style="color: var(--text-muted); font-size: 12px;">矛盾なし</div>`;

    // Render Confidence Score
    const scoreDisplay = container.querySelector("#score-display");
    scoreDisplay.textContent = `${selectedOrderData.total_score || 0}%`;

    // Render Modification History
    const historyTimeline = container.querySelector("#history-timeline");
    const history = selectedOrderData.modification_history ? JSON.parse(selectedOrderData.modification_history) : [];
    historyTimeline.innerHTML = history.length > 0
      ? history.map(item => `
          <div style="padding: 6px; border-left: 2px solid var(--primary); background: rgba(0,0,0,0.15); border-radius: 2px;">
            <div style="font-weight: 500; color: var(--text);">${item.modified_field || "修正"}</div>
            <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">
              ${item.modified_before || ""} → ${item.modified_after || ""}
            </div>
            <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${item.modified_at || ""}</div>
          </div>
        `).join("")
      : `<div style="color: var(--text-muted); font-size: 11px;">修正履歴なし</div>`;

    // Clear form
    container.querySelectorAll('input[name="approval-decision"]').forEach(r => r.checked = false);
    container.querySelector("#approval-comment").value = "";
  }

  // ============================================
  // 3. Event Listeners
  // ============================================
  container.querySelector("#search-button").addEventListener("click", async () => {
    const statusFilter = container.querySelector("#status-filter").value;
    const keyword = container.querySelector("#search-keyword").value.toLowerCase();

    let filtered = allOrders;
    if (statusFilter) {
      filtered = filtered.filter(o => o.current_status === statusFilter);
    }
    if (keyword) {
      filtered = filtered.filter(o =>
        (o.order_id || "").toLowerCase().includes(keyword) ||
        (o.customer_name || "").toLowerCase().includes(keyword)
      );
    }

    renderOrderList(filtered);
  });

  container.querySelector("#submit-button").addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }

    const decision = container.querySelector('input[name="approval-decision"]:checked');
    if (!decision) {
      alert("判定を選択してください");
      return;
    }

    const comment = container.querySelector("#approval-comment").value;

    // Save approval decision
    const payload = {
      order_id: selectedOrderId,
      approval_decision: decision.value,
      approval_comment: comment,
      approved_at: new Date().toISOString(),
      approved_by_user_id: "current-user-id" // Replace with actual user ID
    };

    const saved = await window.aivicApi.save(0, payload);
    if (saved) {
      alert("判定を送信しました");
      // Reload list
      window.aivicApi.list(0).then(rows => {
        allOrders = rows;
        renderOrderList(rows);
        selectedOrderId = null;
        selectedOrderData = null;
        renderDetailPanel();
      });
    }
  });

  container.querySelector("#cancel-button").addEventListener("click", () => {
    selectedOrderId = null;
    selectedOrderData = null;
    container.querySelectorAll(".order-row").forEach(row => row.style.background = "");
    renderDetailPanel();
    container.querySelectorAll('input[name="approval-decision"]').forEach(r => r.checked = false);
    container.querySelector("#approval-comment").value = "";
  });

  // ============================================
  // 4. Initial Load
  // ============================================
  if (tables && tables[0] && tables[0].records) {
    allOrders = tables[0].records;
    renderOrderList(allOrders);
  } else {
    window.aivicApi.list(0).then(rows => {
      allOrders = rows;
      renderOrderList(rows);
    });
  }
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#validation-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const correctionForm = container.querySelector("#correction-form");
  const actionButtons = container.querySelector("#action-buttons");
