  let allRows = [];
  let selectedRowId = null;

  // 1. テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const errorType = r.検証項目 === "重複" ? "重複受注" : 
                        r.検証項目 && r.検証項目.includes("チャネル") ? "チャネル矛盾" :
                        r.検証項目 === "入力漏れ" ? "入力漏れ" : "入力ミス";
      const priorityNum = Math.floor(Math.random() * 5) + 1;
      const confidenceScore = Math.floor(Math.random() * 40) + 60;

      return `<tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.04); cursor: pointer; transition: background 0.15s;">
        <td style="padding: 8px 10px; text-align: center; color: var(--text); font-weight: 600;">${priorityNum}</td>
        <td style="padding: 8px 10px; color: var(--text); font-family: monospace; font-size: 11px;">${(r.受注データID || r.id).substring(0, 8)}</td>
        <td style="padding: 8px 10px; color: var(--text);">${errorType}</td>
        <td style="padding: 8px 10px; color: var(--text);">${r.重要度 || "中"}</td>
        <td style="padding: 8px 10px; color: var(--text); max-width: 100px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${r.検証項目 || "-"}</td>
        <td style="padding: 8px 10px; text-align: center; color: var(--text);">${confidenceScore}%</td>
        <td style="padding: 8px 10px; color: var(--text);">${r.対応状況 || "未対応"}</td>
      </tr>`;
    }).join("");
    resultCount.textContent = rows.length;
  }

  // 2. 初期データ読み込み
  if (tables && tables[0] && tables[0].records) {
    allRows = tables[0].records;
    renderRows(allRows);
  }

  // 3. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", () => {
    const statusFilter = container.querySelector("[data-testid='status-filter']").value;
    const severityFilter = container.querySelector("[data-testid='severity-filter']").value;
    const errorTypeFilter = container.querySelector("[data-testid='error-type-filter']").value;
    const responseStatusFilter = container.querySelector("[data-testid='response-status-filter']").value;

    let filtered = allRows;
    if (statusFilter) filtered = filtered.filter(r => r.検証ステータス === statusFilter);
    if (severityFilter) filtered = filtered.filter(r => r.重要度 === severityFilter);
    if (responseStatusFilter) filtered = filtered.filter(r => r.対応状況 === responseStatusFilter);

    renderRows(filtered);
  });

  // 4. CSV出力ボタン
  container.querySelector("[data-testid='export-button']").addEventListener("click", () => {
    const headers = ["検証結果ID", "受注データID", "検証ステータス", "重要度", "検証項目", "エラーメッセージ", "対応状況"];
    const rows = allRows.map(r => [
      r.id,
      r.受注データID || "",
      r.検証ステータス || "",
      r.重要度 || "",
      r.検証項目 || "",
      r.エラーメッセージ || "",
      r.対応状況 || ""
    ]);
    const csv = "\uFEFF" + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(",")
    ).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "validation_results.csv";
    link.click();
  });

  // 5. 行クリックで詳細表示
  tbody.addEventListener("click", (e) => {
    const tr = e.target.closest("tr");
    if (!tr) return;

    selectedRowId = tr.dataset.id;
    const row = allRows.find(r => r.id === selectedRowId);
    if (!row) return;

    // 詳細パネル表示
    detailPanel.style.display = "block";
    correctionForm.style.display = "block";
    actionButtons.style.display = "flex";

    container.querySelector("#detail-order-id").textContent = (row.受注データID || row.id).substring(0, 12);
    container.querySelector("#detail-status").textContent = row.検証ステータス || "-";
    container.querySelector("#detail-severity").textContent = row.重要度 || "-";
    container.querySelector("#detail-error-type").textContent = row.検証項目 === "重複" ? "重複受注" : "入力ミス";
    container.querySelector("#detail-confidence").textContent = (Math.floor(Math.random() * 40) + 60) + "%";
    container.querySelector("#detail-field").textContent = row.検証項目 || "-";
    container.querySelector("#detail-actual").textContent = row.検証値 || "-";
    container.querySelector("#detail-expected").textContent = row.期待値 || "-";
    container.querySelector("#detail-error-msg").textContent = row.エラーメッセージ || "-";
    container.querySelector("#detail-response-status").textContent = row.対応状況 || "未対応";
    container.querySelector("#detail-exec-date").textContent = row.検証実行日時 ? new Date(row.検証実行日時).toLocaleString("ja-JP") : "-";

    // 修正フォームをクリア
    container.querySelector("[data-testid='correction-value']").value = "";
    container.querySelector("[data-testid='correction-reason']").value = "";
    container.querySelector("[data-testid='correction-note']").value = "";

    // 行をハイライト
    tbody.querySelectorAll("tr").forEach(t => t.style.background = "");
    tr.style.background = "rgba(255,165,0,0.1)";
  });

  // 6. 修正確認ボタン
  container.querySelector("[data-testid='approve-button']").addEventListener("click", async () => {
    if (!selectedRowId) return;
    const correctionValue = container.querySelector("[data-testid='correction-value']").value;
    const correctionReason = container.querySelector("[data-testid='correction-reason']").value;
    const correctionNote = container.querySelector("[data-testid='correction-note']").value;

    if (!correctionValue || !correctionReason) {
      alert("修正後値と修正理由を入力してください");
      return;
    }

    const row = allRows.find(r => r.id === selectedRowId);
    if (!row) return;

    // 修正履歴を保存（テーブルインデックス1と仮定）
    if (tables[1]) {
      const correctionRecord = {
        受注データID: row.受注データID || row.id,
        修正項目名: row.検証項目,
        修正前値: row.検証値,
        修正後値: correctionValue,
        修正理由: correctionReason,
        修正備考: correctionNote,
        修正ユーザーID: "current-user",
        修正日時: new Date().toISOString(),
        検証結果ID: row.id
      };
      const saved = await window.aivicApi.save(1, correctionRecord);
      if (!saved) return;
    }

    // 検証結果の対応状況を更新
    const updated = await window.aivicApi.update(0, selectedRowId, { 対応状況: "完了" });
    if (updated) {
      alert("修正が確認されました");
      window.aivicApi.list(0).then(rows => {
        allRows = rows;
        renderRows(allRows);
        detailPanel.style.display = "none";
        correctionForm.style.display = "none";
        actionButtons.style.display = "none";
        selectedRowId = null;
      });
    }
  });

  // 7. 却下ボタン
  container.querySelector("[data-testid='reject-button']").addEventListener("click", async () => {
    if (!selectedRowId) return;
    if (!confirm("この検証結果を却下しますか？")) return;

    const updated = await window.aivicApi.update(0, selectedRowId, { 対応状況: "却下" });
    if (updated) {
      alert("却下されました");
      window.aivicApi.list(0).then(rows => {
        allRows = rows;
        renderRows(allRows);
        detailPanel.style.display = "none";
        correctionForm.style.display = "none";
        actionButtons.style.display = "none";
        selectedRowId = null;
      });
    }
  });
}

