  let beforeData = {};
  let afterData = {};
  let modifiedItems = [];
  let beforeValidationResult = null;
  let afterValidationResult = null;
  let currentChannel = null;
  let beforeConfidenceScore = 0;
  let afterConfidenceScore = 0;

  // URL パラメータから受注IDを取得
  const urlParams = new URLSearchParams(window.location.search);
  currentOrderId = urlParams.get('orderId') || 'ORD-2024-001';
  currentValidationResultId = urlParams.get('validationResultId') || null;

  // 修正前後データの比較テーブル描画
  function renderBeforeData(data) {
    const tbody = container.querySelector('#before-data-tbody');
    if (!data || Object.keys(data).length === 0) {
      tbody.innerHTML = '<tr><td style="padding: 6px; color: var(--text-muted);">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = Object.entries(data)
      .map(([key, value]) => `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px; color: var(--text-muted); font-size: 11px; width: 40%;">${key}</td>
          <td style="padding: 6px; color: var(--text); font-size: 11px; word-break: break-all;">${value || '—'}</td>
        </tr>
      `)
      .join('');
  }

  function renderAfterData(data) {
    const tbody = container.querySelector('#after-data-tbody');
    if (!data || Object.keys(data).length === 0) {
      tbody.innerHTML = '<tr><td style="padding: 6px; color: var(--text-muted);">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = Object.entries(data)
      .map(([key, value]) => {
        const isMofidied = beforeData[key] !== value;
        const bgColor = isMofidied ? 'rgba(255,152,0,0.1)' : 'transparent';
        const borderColor = isMofidied ? 'rgba(255,152,0,0.3)' : 'rgba(255,255,255,0.05)';
        return `
          <tr style="border-bottom: 1px solid ${borderColor}; background: ${bgColor};">
            <td style="padding: 6px; color: var(--text-muted); font-size: 11px; width: 40%;">${key}</td>
            <td style="padding: 6px; color: var(--text); font-size: 11px; word-break: break-all; font-weight: ${isMofidied ? '600' : '400'};">${value || '—'}</td>
          </tr>
        `;
      })
      .join('');
  }

  function renderModifiedItems(items) {
    const tbody = container.querySelector('#modified-items-tbody');
    if (!items || items.length === 0) {
      tbody.innerHTML = '<tr><td colspan="3" style="padding: 6px; color: var(--text-muted);">修正項目なし</td></tr>';
      return;
    }
    tbody.innerHTML = items
      .map(item => `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px; color: var(--text); font-size: 11px;">${item.itemName || '—'}</td>
          <td style="padding: 6px; color: var(--text-muted); font-size: 11px; word-break: break-all;">${item.beforeValue || '—'}</td>
          <td style="padding: 6px; color: #4caf50; font-size: 11px; word-break: break-all; font-weight: 600;">${item.afterValue || '—'}</td>
        </tr>
      `)
      .join('');
  }

  // 初期データの読み込みと表示
  async function initializeScreen() {
    try {
      // 修正対象の受注データを取得（ここではダミーデータを使用）
      beforeData = {
        '受注ID': currentOrderId,
        '顧客名': '株式会社ABC',
        '受注金額': '150,000',
        '受注日': '2024-01-15',
        '配送先': '東京都渋谷区',
        'ステータス': '処理中'
      };

      afterData = {
        '受注ID': currentOrderId,
        '顧客名': '株式会社ABC',
        '受注金額': '160,000',
        '受注日': '2024-01-15',
        '配送先': '東京都渋谷区',
        'ステータス': '確認済み'
      };

      modifiedItems = [
        { itemName: '受注金額', beforeValue: '150,000', afterValue: '160,000' },
        { itemName: 'ステータス', beforeValue: '処理中', afterValue: '確認済み' }
      ];

      beforeValidationResult = '不合格（金額エラー）';
      afterValidationResult = '合格';
      beforeConfidenceScore = 65;
      afterConfidenceScore = 92;
      currentChannel = 'Web注文';

      // 表示を更新
      container.querySelector('#order-id-display').textContent = currentOrderId;
      container.querySelector('#modifier-display').textContent = '山田太郎';
      container.querySelector('#modification-datetime-display').textContent = new Date().toLocaleString('ja-JP');
      container.querySelector('#before-validation-result').textContent = beforeValidationResult;
      container.querySelector('#after-validation-result').textContent = afterValidationResult;
      container.querySelector('#channel-display').textContent = currentChannel;
      container.querySelector('#confidence-score-display').textContent = `${beforeConfidenceScore} → ${afterConfidenceScore}`;
      container.querySelector('#validation-result-id-input').value = currentValidationResultId || 'VAL-2024-001';

      renderBeforeData(beforeData);
      renderAfterData(afterData);
      renderModifiedItems(modifiedItems);

    } catch (error) {
      console.error('初期化エラー:', error);
      container.querySelector('#error-message').style.display = 'block';
      container.querySelector('#error-message').textContent = '画面の初期化に失敗しました';
    }
  }

  // 保存処理
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const reason = container.querySelector('#modification-reason').value;
    const notes = container.querySelector('#modification-notes').value;
    const confidenceChange = parseInt(container.querySelector('#confidence-change').value) || 0;

    if (!reason) {
      container.querySelector('#error-message').style.display = 'block';
      container.querySelector('#error-message').textContent = '修正理由を選択してください';
      return;
    }

    try {
      // 修正履歴レコードの作成
      const modificationHistoryRecord = {
        修正履歴ID: 'MH-' + Date.now(),
        受注データID: currentOrderId,
        修正項目名: modifiedItems.map(m => m.itemName).join(', '),
        修正前値: JSON.stringify(beforeData),
        修正後値: JSON.stringify(afterData),
        修正理由: reason,
        修正備考: notes,
        修正ユーザーID: 'USER-001',
        修正日時: new Date().toISOString(),
        検証結果ID: currentValidationResultId,
        作成日時: new Date().toISOString()
      };

      // 修正履歴を保存
      const savedHistory = await window.aivicApi.save(modificationHistoryTableIndex, modificationHistoryRecord);

      // 信頼度スコアを更新
      const newConfidenceScore = Math.max(0, Math.min(100, afterConfidenceScore + confidenceChange));
      const confidenceScoreRecord = {
        信頼度スコアID: 'CS-' + Date.now(),
        受注データID: currentOrderId,
        検証結果ID: currentValidationResultId,
        総合スコア: newConfidenceScore,
        完全性スコア: Math.max(0, Math.min(100, 85 + confidenceChange)),
        正確性スコア: Math.max(0, Math.min(100, 90 + confidenceChange)),
        一貫性スコア: Math.max(0, Math.min(100, 88 + confidenceChange)),
        スコア計算日時: new Date().toISOString(),
        警告フラグ: newConfidenceScore < 70,
        警告レベル: newConfidenceScore < 70 ? '中' : null,
        備考: `修正による信頼度スコア更新: ${afterConfidenceScore} → ${newConfidenceScore}`,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者ID: 'USER-001'
      };

      const savedScore = await window.aivicApi.save(confidenceScoreTableIndex, confidenceScoreRecord);

      // 成功メッセージ表示
      container.querySelector('#error-message').style.display = 'none';
      container.querySelector('#save-message').style.display = 'block';
      container.querySelector('#save-message').textContent = '修正履歴を保存しました';

      // 3秒後に前の画面に戻る
      setTimeout(() => {
        window.showScreen('scr-1781413282852'); // 受注データ詳細確認・修正画面へ
      }, 2000);

    } catch (error) {
      console.error('保存エラー:', error);
      container.querySelector('#error-message').style.display = 'block';
      container.querySelector('#error-message').textContent = '修正履歴の保存に失敗しました';
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('修正を中止しますか？')) {
      window.showScreen('scr-1781413282852'); // 受注データ詳細確認・修正画面へ
    }
  });

  // 初期化実行
  initializeScreen();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#order-tbody");
  const filterOrderId = container.querySelector("#filter-order-id");
  const filterDateFrom = container.querySelector("#filter-date-from");
  const filterDateTo = container.querySelector("#filter-date-to");
  const filterStatus = container.querySelector("#filter-status");
  const filterChannel = container.querySelector("#filter-channel");
  const filterScoreMin = container.querySelector("#filter-score-min");
  const filterScoreMax = container.querySelector("#filter-score-max");
  const btnSearch = container.querySelector("#btn-search");
  const btnReset = container.querySelector("#btn-reset");
  const btnExportCsv = container.querySelector("#btn-export-csv");
  const btnDashboard = container.querySelector("#btn-dashboard");
  const btnPriorityList = container.querySelector("#btn-priority-list");

  // ステータスバッジの色付け
  function getStatusBadgeStyle(status) {
    const styles = {
      "合格": "background: rgba(76, 175, 80, 0.2); color: #4CAF50; border-left: 3px solid #4CAF50;",
      "不合格": "background: rgba(244, 67, 54, 0.2); color: #F44336; border-left: 3px solid #F44336;",
      "警告": "background: rgba(255, 193, 7, 0.2); color: #FFC107; border-left: 3px solid #FFC107;",
      "保留": "background: rgba(158, 158, 158, 0.2); color: #9E9E9E; border-left: 3px solid #9E9E9E;"
    };
    return styles[status] || "background: var(--bg-card); color: var(--text);";
  }

  // 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const statusBadge = getStatusBadgeStyle(r.検証ステータス || "保留");
      const scoreColor = (r.総合スコア || 0) >= 80 ? "#4CAF50" : (r.総合スコア || 0) >= 60 ? "#FFC107" : "#F44336";
      const errorCount = (r.エラー件数 || 0);
      const errorSummary = errorCount > 0 ? `エラー ${errorCount}件` : "正常";

      return `
        <tr data-id="${r.検証結果ID || r.id}" style="border-bottom: 1px solid var(--border); hover: background: rgba(255,255,255,0.04);">
          <td style="padding: 8px; color: var(--text);">${r.受注データID || r.受注ID || "-"}</td>
          <td style="padding: 8px; color: var(--text); font-size: 12px;">${r.受注日時 ? new Date(r.受注日時).toLocaleString('ja-JP') : "-"}</td>
          <td style="padding: 8px; color: var(--text);">${r.チャネル名 || r.チャネル || "-"}</td>
          <td style="padding: 8px;">
            <span style="padding: 4px 8px; border-radius: 3px; font-size: 12px; font-weight: 500; ${statusBadge}">
              ${r.検証ステータス || "保留"}
            </span>
          </td>
          <td style="padding: 8px; text-align: center; color: ${scoreColor}; font-weight: 600;">
            ${r.総合スコア || 0}
          </td>
          <td style="padding: 8px; color: var(--text); font-size: 12px;">
            <span style="color: ${errorCount > 0 ? '#F44336' : '#4CAF50'};">
              ${errorSummary}
            </span>
            ${r.重要度 ? ` / 重要度: ${r.重要度}` : ""}
          </td>
          <td style="padding: 8px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${r.検証結果ID || r.id}" style="padding: 4px 8px; font-size: 12px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 初期データ描画
  renderRows(tables[0]?.records || []);

  // 検索処理
  btnSearch.addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      const orderId = (r.受注データID || r.受注ID || "").toString().toLowerCase();
      const keyword = filterOrderId.value.toLowerCase();
      if (keyword && !orderId.includes(keyword)) return false;

      const dateFrom = filterDateFrom.value ? new Date(filterDateFrom.value) : null;
      const dateTo = filterDateTo.value ? new Date(filterDateTo.value) : null;
      const orderDate = r.受注日時 ? new Date(r.受注日時) : null;
      if (dateFrom && orderDate && orderDate < dateFrom) return false;
      if (dateTo && orderDate && orderDate > dateTo) return false;

      const status = filterStatus.value;
      if (status && r.検証ステータス !== status) return false;

      const channel = filterChannel.value;
      if (channel && (r.チャネル名 || r.チャネル) !== channel) return false;

      const scoreMin = filterScoreMin.value ? parseInt(filterScoreMin.value) : 0;
      const scoreMax = filterScoreMax.value ? parseInt(filterScoreMax.value) : 100;
      const score = r.総合スコア || 0;
      if (score < scoreMin || score > scoreMax) return false;

      return true;
    });

    renderRows(filtered);
  });

  // リセット処理
  btnReset.addEventListener("click", () => {
    filterOrderId.value = "";
    filterDateFrom.value = "";
    filterDateTo.value = "";
    filterStatus.value = "";
    filterChannel.value = "";
    filterScoreMin.value = "";
    filterScoreMax.value = "";
    renderRows(tables[0]?.records || []);
  });

  // 詳細ボタンのイベントデリゲーション
  container.addEventListener("click", async e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細確認・修正画面へ遷移
      window.showScreen("scr-1781413282852");
    }
  });

  // CSVエクスポート
  btnExportCsv.addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows || rows.length === 0) {
      alert("エクスポート対象のデータがありません");
      return;
    }

    const headers = ["受注ID", "受注日時", "チャネル", "検証ステータス", "信頼度スコア", "エラー件数", "重要度", "対応状況"];
    const csvContent = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...rows.map(r => [
        r.受注データID || r.受注ID || "",
        r.受注日時 ? new Date(r.受注日時).toLocaleString('ja-JP') : "",
        r.チャネル名 || r.チャネル || "",
        r.検証ステータス || "",
        r.総合スコア || 0,
        r.エラー件数 || 0,
        r.重要度 || "",
        r.対応状況 || ""
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `受注ステータス照会_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // ダッシュボードボタン
  btnDashboard.addEventListener("click", () => {
    window.showScreen("scr-1781413262699");
  });

  // 修正対象優先度リストボタン
  btnPriorityList.addEventListener("click", () => {
    window.showScreen("scr-1781413354977");
  });
}

function(container, apiUrl, tables) {
