        <td style="padding: 8px 10px; font-size: 12px;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: rgba(${statusColor === "#4ade80" ? "74,222,128" : statusColor === "#ef4444" ? "239,68,68" : statusColor === "#f59e0b" ? "245,158,11" : "107,114,128"},0.2); color: ${statusColor}; font-weight: 500;">
