        </td>
        <td style="padding: 8px 10px; text-align: center; color: var(--text); font-size: 12px; font-weight: 500;">${r.信頼度スコア || "—"}</td>
        <td style="padding: 8px 10px; text-align: center; font-size: 12px;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: rgba(${severityColor === "#dc2626" ? "220,38,38" : severityColor === "#f97316" ? "249,115,22" : severityColor === "#eab308" ? "234,179,8" : "132,204,22"},0.2); color: ${severityColor}; font-weight: 500;">
            ${r.重要度 || "—"}
