      if (confidenceFilter === "high") {
        filtered = filtered.filter(r => parseInt(r.信頼度スコア || 0) >= 80);
      } else if (confidenceFilter === "medium") {
        filtered = filtered.filter(r => parseInt(r.信頼度スコア || 0) >= 50 && parseInt(r.信頼度スコア || 0) < 80);
      } else if (confidenceFilter === "low") {
        filtered = filtered.filter(r => parseInt(r.信頼度スコア || 0) < 50);
