        <div style="padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,0.08);">
          <span style="color: var(--text-muted);">修正者:</span> システム<br>
          <span style="color: var(--text-muted);">修正日時:</span> ${new Date().toLocaleString('ja-JP')}<br>
          <span style="color: var(--text-muted);">修正理由:</span> 検証エラー
