    selectedCount.textContent = "1";
  });

  // 5. 詳細確認ボタン
  container.querySelector("#btn-detail").addEventListener("click", () => {
    if (!selectedRowId) {
      alert("行を選択してください");
      return;
    }
    const row = allRows.find(r => r.検証結果ID === selectedRowId);
    if (!row) return;

    modalDetailContent.innerHTML = `
      <div style="display: grid; gap: 12px;">
        <div>
          <span style="color: var(--text-muted); font-size: 12px;">受注ID</span><br>
          <span style="color: var(--text); font-weight: 500;">${row.受注データID || "—"}</span>
        </div>
        <div>
          <span style="color: var(--text-muted); font-size: 12px;">検証ステータス</span><br>
          <span style="color: var(--text); font-weight: 500;">${row.検証ステータス || "—"}</span>
        </div>
        <div>
          <span style="color: var(--text-muted); font-size: 12px;">検証項目</span><br>
          <span style="color: var(--text); font-weight: 500;">${row.検証項目 || "—"}</span>
        </div>
        <div>
          <span style="color: var(--text-muted); font-size: 12px;">エラーメッセージ</span><br>
          <span style="color: var(--text);">${row.エラーメッセージ || "—"}</span>
        </div>
        <div>
          <span style="color: var(--text-muted); font-size: 12px;">対応状況</span><br>
          <span style="color: var(--text); font-weight: 500;">${row.対応状況 || "未対応"}</span>
        </div>
      </div>
    `;
    modalDetail.style.display = "flex";
  });

  modalDetailClose.addEventListener("click", () => {
    modalDetail.style.display = "none";
  });

  modalDetailEdit.addEventListener("click", () => {
    window.showScreen("scr-1781413282852");
  });

  // 6. ナビゲーションボタン
  container.querySelector("#btn-duplicate").addEventListener("click", () => {
    window.showScreen("scr-1781413297335");
  });

  container.querySelector("#btn-contradiction").addEventListener("click", () => {
    window.showScreen("scr-1781413311177");
  });

  container.querySelector("#btn-missing").addEventListener("click", () => {
    window.showScreen("scr-1781413340116");
  });

  container.querySelector("#btn-priority").addEventListener("click", () => {
    window.showScreen("scr-1781413354977");
  });

  container.querySelector("#btn-approve").addEventListener("click", () => {
    window.showScreen("scr-1781413369295");
  });

  // 7. CSV出力
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows || rows.length === 0) {
      alert("出力するデータがありません");
      return;
    }

    const headers = ["受注データID", "チャネル", "検証項目", "検証ステータス", "信頼度スコア", "重要度", "対応状況", "エラーコード", "エラーメッセージ"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => [
        r.受注データID || "",
        r.チャネル || "",
        r.検証項目 || "",
        r.検証ステータス || "",
        r.信頼度スコア || "",
        r.重要度 || "",
        r.対応状況 || "",
        r.エラーコード || "",
        `"${(r.エラーメッセージ || "").replace(/"/g, '""')}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `validation-results-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const TABLE_PRIORITY_LIST = 0;      // 修正対象優先度リスト
  const TABLE_VALIDATION_RESULT = 1;  // 受注データ検証結果
  const TABLE_MODIFICATION_HISTORY = 2; // 受注データ修正履歴
  const TABLE_CONFIDENCE_SCORE = 3;   // 信頼度スコア
  const TABLE_DUPLICATE_DETECTION = 4; // 重複受注検出結果
  const TABLE_CHANNEL_CONFLICT = 5;   // チャネル間矛盾検出結果
  const TABLE_INPUT_OMISSION = 6;     // 入力漏れ検出結果

  let currentSelectedOrderId = null;
  let allPriorityData = [];
  let allValidationData = [];
  let allModificationHistory = [];

  // ========== 1. 優先度リスト再描画関数 ==========
  function renderPriorityList(rows) {
    const listContainer = container.querySelector("#priority-list");
    listContainer.innerHTML = rows.map(row => {
      const priorityLabel = ["", "最高", "高", "中", "低", "最低"][row.優先度レベル || 3];
      const statusColor = {
        "未対応": "#ff6b6b",
        "対応中": "#ffa500",
        "完了": "#51cf66",
        "保留": "#748ffc"
      }[row.修正ステータス] || "#9fb0d1";

      return `
        <div class="priority-item" data-id="${row.優先度リストID}" style="
          padding: 10px 12px;
          border-bottom: 1px solid var(--border);
          cursor: pointer;
          transition: background 0.2s;
          background: var(--bg-main);
        " onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background='var(--bg-main)'">
          <div style="display: flex; justify-content: space-between; align-items: start; margin-bottom: 6px;">
            <div style="font-weight: 600; color: var(--text); font-size: 13px;">
              ${row.受注データID ? row.受注データID.substring(0, 8) : "N/A"}
            </div>
            <span style="
              display: inline-block;
              padding: 2px 6px;
              border-radius: 3px;
              font-size: 11px;
              font-weight: 600;
              background: ${statusColor};
              color: #fff;
            ">${row.修正ステータス || "未対応"}</span>
          </div>
          <div style="font-size: 12px; color: var(--text-muted); margin-bottom: 4px;">
            優先度: <strong>${priorityLabel}</strong>
          </div>
          <div style="font-size: 12px; color: var(--text-muted);">
            ${row.エラー分類 || "不明"}
          </div>
          <div style="font-size: 11px; color: var(--text-muted); margin-top: 4px;">
            信頼度: ${row.信頼度スコア || "N/A"}%
          </div>
        </div>
      `;
    }).join("");

    // イベントデリゲーション：優先度リスト行クリック
    container.querySelectorAll(".priority-item").forEach(item => {
      item.addEventListener("click", () => {
        container.querySelectorAll(".priority-item").forEach(i => i.style.background = "var(--bg-main)");
        item.style.background = "rgba(255,165,0,0.15)";
        currentSelectedOrderId = item.dataset.id;
        loadDetailPanel(item.dataset.id);
      });
    });
  }

  // ========== 2. 詳細パネル読み込み関数 ==========
  function loadDetailPanel(priorityListId) {
    const priorityRow = allPriorityData.find(r => r.優先度リストID === priorityListId);
    if (!priorityRow) return;

    const orderId = priorityRow.受注データID;
    const validationRows = allValidationData.filter(r => r.受注データID === orderId);
    const modHistory = allModificationHistory.filter(r => r.受注データID === orderId);

    const detailPanel = container.querySelector("#detail-panel");
    const emptyState = container.querySelector("#empty-state");

    // 検証エラーセクション
    const validationHtml = validationRows.length > 0 ? `
      <div style="margin-bottom: 16px; padding: 12px; background: var(--bg-card); border-radius: 4px; border-left: 3px solid #ff6b6b;">
        <div style="font-size: 12px; font-weight: 600; color: var(--text); margin-bottom: 8px;">検証エラー</div>
        ${validationRows.map(v => `
          <div style="font-size: 12px; color: var(--text-muted); margin-bottom: 4px; padding: 4px 0; border-bottom: 1px solid rgba(255,255,255,0.08);">
            <strong>${v.検証項目}</strong>: ${v.エラーメッセージ || "エラー"}
            <br><span style="font-size: 11px;">期待値: ${v.期待値 || "N/A"} → 実際: ${v.検証値 || "N/A"}</span>
          </div>
        `).join("")}
      </div>
    ` : "";

    // 修正フォーム
    const formHtml = `
      <div style="margin-bottom: 16px;">
        <div style="font-size: 12px; font-weight: 600; color: var(--text); margin-bottom: 8px;">修正内容</div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
          <div>
            <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">顧客名</label>
            <input type="text" class="modify-customer-name" data-testid="customer-name-input" placeholder="顧客名" style="width: 100%; padding: 6px 8px; border: 1px solid rgba(255,255,255,0.18); border-radius: 4px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px;">
          </div>
          <div>
            <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">受注金額</label>
            <input type="number" class="modify-amount" data-testid="amount-input" placeholder="金額" style="width: 100%; padding: 6px 8px; border: 1px solid rgba(255,255,255,0.18); border-radius: 4px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px;">
          </div>
          <div>
            <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">数量</label>
            <input type="number" class="modify-quantity" data-testid="quantity-input" placeholder="数量" style="width: 100%; padding: 6px 8px; border: 1px solid rgba(255,255,255,0.18); border-radius: 4px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px;">
          </div>
          <div>
            <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">商品コード</label>
            <input type="text" class="modify-product-code" data-testid="product-code-input" placeholder="商品コード" style="width: 100%; padding: 6px 8px; border: 1px solid rgba(255,255,255,0.18); border-radius: 4px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px;">
          </div>
          <div>
            <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">配送先住所</label>
            <input type="text" class="modify-address" data-testid="address-input" placeholder="住所" style="width: 100%; padding: 6px 8px; border: 1px solid rgba(255,255,255,0.18); border-radius: 4px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px;">
          </div>
          <div>
            <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">修正理由</label>
            <select class="modify-reason" data-testid="reason-select" style="width: 100%; padding: 6px 8px; border: 1px solid rgba(255,255,255,0.18); border-radius: 4px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px;">
              <option value="">選択</option>
              <option value="入力誤り">入力誤り</option>
              <option value="検証エラー">検証エラー</option>
              <option value="顧客確認">顧客確認</option>
              <option value="システム不具合">システム不具合</option>
              <option value="重複排除">重複排除</option>
            </select>
          </div>
        </div>
        <div style="margin-top: 12px;">
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">修正備考</label>
          <textarea class="modify-notes" data-testid="notes-textarea" placeholder="修正に関する詳細説明" style="width: 100%; padding: 6px 8px; border: 1px solid rgba(255,255,255,0.18); border-radius: 4px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px; min-height: 60px; resize: vertical;"></textarea>
        </div>
      </div>
    `;

    // 修正履歴セクション
    const historyHtml = modHistory.length > 0 ? `
      <div style="margin-top: 16px; padding: 12px; background: var(--bg-card); border-radius: 4px;">
        <div style="font-size: 12px; font-weight: 600; color: var(--text); margin-bottom: 8px;">修正履歴</div>
        ${modHistory.slice(0, 5).map(h => `
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 6px; padding-bottom: 6px; border-bottom: 1px solid rgba(255,255,255,0.08);">
            <strong>${h.修正項目名}</strong>: ${h.修正前値} → ${h.修正後値}
            <br><span style="font-size: 10px;">${h.修正理由} | ${new Date(h.修正日時).toLocaleString()}</span>
          </div>
        `).join("")}
      </div>
    ` : "";

    detailPanel.innerHTML = validationHtml + formHtml + historyHtml;
    detailPanel.style.display = "block";
    emptyState.style.display = "none";
  }

  // ========== 3. 初期データ読み込み＆描画 ==========
  async function initializeData() {
    // 優先度リストデータ取得
    const priorityData = await window.aivicApi.list(TABLE_PRIORITY_LIST);
    if (priorityData) {
      allPriorityData = priorityData;
      renderPriorityList(priorityData);
    }

    // 検証結果データ取得
    const validationData = await window.aivicApi.list(TABLE_VALIDATION_RESULT);
    if (validationData) {
      allValidationData = validationData;
    }

    // 修正履歴データ取得
    const modHistoryData = await window.aivicApi.list(TABLE_MODIFICATION_HISTORY);
    if (modHistoryData) {
      allModificationHistory = modHistoryData;
    }
  }

  // ========== 4. 検索ボタン ==========
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#search-keyword").value.toLowerCase();
    const priorityFilter = container.querySelector("#filter-priority").value;
    const statusFilter = container.querySelector("#filter-status").value;

    let filtered = allPriorityData;

    if (keyword) {
      filtered = filtered.filter(r => 
        (r.受注データID || "").toLowerCase().includes(keyword) ||
        (r.エラー分類 || "").toLowerCase().includes(keyword)
      );
    }

    if (priorityFilter) {
      filtered = filtered.filter(r => r.優先度レベル == priorityFilter);
    }

    if (statusFilter) {
      filtered = filtered.filter(r => r.修正ステータス === statusFilter);
    }

    renderPriorityList(filtered);
  });

  // ========== 5. 修正保存ボタン ==========
  container.querySelector("#btn-save-modification").addEventListener("click", async () => {
    if (!currentSelectedOrderId) {
      alert("修正対象を選択してください");
      return;
    }

    const customerName = container.querySelector(".modify-customer-name").value;
    const amount = container.querySelector(".modify-amount").value;
    const quantity = container.querySelector(".modify-quantity").value;
    const productCode = container.querySelector(".modify-product-code").value;
    const address = container.querySelector(".modify-address").value;
    const reason = container.querySelector(".modify-reason").value;
    const notes = container.querySelector(".modify-notes").value;

    if (!reason) {
      alert("修正理由を選択してください");
      return;
    }

    // 修正履歴を保存
    const modificationItems = [];
    if (customerName) modificationItems.push({ 修正項目名: "顧客名", 修正前値: "前値", 修正後値: customerName, 修正理由: reason });
    if (amount) modificationItems.push({ 修正項目名: "受注金額", 修正前値: "前値", 修正後値: amount, 修正理由: reason });
    if (quantity) modificationItems.push({ 修正項目名: "数量", 修正前値: "前値", 修正後値: quantity, 修正理由: reason });
    if (productCode) modificationItems.push({ 修正項目名: "商品コード", 修正前値: "前値", 修正後値: productCode, 修正理由: reason });
    if (address) modificationItems.push({ 修正項目名: "配送先住所", 修正前値: "前値", 修正後値: address, 修正理由: reason });

    for (const item of modificationItems) {
      const saved = await window.aivicApi.save(TABLE_MODIFICATION_HISTORY, {
        受注データID: currentSelectedOrderId,
        修正項目名: item.修正項目名,
        修正前値: item.修正前値,
        修正後値: item.修正後値,
        修正理由: item.修正理由,
        修正備考: notes,
        修正ユーザーID: "current-user-id",
        修正日時: new Date().toISOString()
      });
    }

    // 優先度リストのステータスを「完了」に更新
    const priorityRow = allPriorityData.find(r => r.優先度リストID === currentSelectedOrderId);
    if (priorityRow) {
      await window.aivicApi.update(TABLE_PRIORITY_LIST, currentSelectedOrderId, {
        修正ステータス: "完了"
      });
    }

    alert("修正内容を保存しました");
    await initializeData();
    container.querySelector("#detail-panel").style.display = "none";
    container.querySelector("#empty-state").style.display = "flex";
    currentSelectedOrderId = null;
  });

  // ========== 6. キャンセルボタン ==========
  container.querySelector("#btn-cancel-modification").addEventListener("click", () => {
    container.querySelector("#detail-panel").style.display = "none";
    container.querySelector("#empty-state").style.display = "flex";
    currentSelectedOrderId = null;
  });

  // ========== 7. 再検証ボタン ==========
  container.querySelector("#btn-revalidate").addEventListener("click", async () => {
    if (!currentSelectedOrderId) {
      alert("修正対象を選択してください");
      return;
    }
    alert("再検証を実行します（処理中...）");
    // 実際の再検証処理は別画面で実装
    window.showScreen("scr-1781413613168"); // 修正データ再検証処理
  });

  // ========== 8. 基幹連携ボタン ==========
  container.querySelector("#btn-sync-erp").addEventListener("click", async () => {
    if (!currentSelectedOrderId) {
      alert("修正対象を選択してください");
      return;
    }
    alert("基幹システムへの連携を実行します");
    // 実際の連携処理は別画面で実装
    window.showScreen("scr-1781413369295"); // 連携承認フロー実行画面
  });

  // ========== 9. CSV出力ボタン ==========
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    const rows = allPriorityData;
    if (rows.length === 0) {
      alert("出力するデータがありません");
      return;
    }

    const headers = ["受注ID", "優先度", "エラー分類", "ステータス", "信頼度スコア", "割り当て先"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => [
        r.受注データID || "",
        ["", "最高", "高", "中", "低", "最低"][r.優先度レベル || 3],
        r.エラー分類 || "",
        r.修正ステータス || "",
        r.信頼度スコア || "",
        r.割り当て先ユーザーID || ""
      ].map(v => `"${v}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `修正対象優先度リスト_${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });

  // ========== 10. 初期化実行 ==========
  initializeData();
}
